  transform: scale(1.3) !important;
  z-index: 2 !important;
  transition: all 0.3s;
  overflow: visible;
}
.slider .swiper-slide-active .slider_text {
  opacity: 1;
}
.slider .slider_text {
  background: rgba(34, 35, 43, 0.55);
  backdrop-filter: blur(6px);
  position: absolute;
  bottom: 10px;
  right: 50%;
  transform: translateX(50%);
  width: 95%;
  padding: 8px;
  color: var(--primaryTextColor);
  border-radius: 5px;
  opacity: 0;
