/* ---------------------------------------------------------------------------
   Cinematic slider (inc/template_parts/slider/cinematic.php)
   --------------------------------------------------------------------------- */
.ms-cinema {
  --ms-cinema-h: 470px;
  --ms-cinema-art: 300px;
  --ms-cinema-radius: 26px;
  --ms-cinema-delay: 6000ms;
  --ms-cinema-fg: var(--ms-white);
  --ms-cinema-fg-dim: rgba(255, 255, 255, 0.72);
  --ms-cinema-line: rgba(255, 255, 255, 0.18);
  --ms-cinema-fill: rgba(255, 255, 255, 0.1);
  --ms-cinema-fill-hover: rgba(255, 255, 255, 0.2);
  --ms-cinema-track: rgba(255, 255, 255, 0.25);
  --ms-cinema-title-shadow: 0 6px 26px rgba(0, 0, 0, 0.55);
  --ms-cinema-cover-shadow: 0 26px 50px -16px rgba(0, 0, 0, 0.8);
  position: relative;
  isolation: isolate;
  overflow: hidden;
  margin: 30px 0 50px;
  min-height: var(--ms-cinema-h);
  border-radius: var(--ms-cinema-radius);
  box-shadow: 0 30px 60px -28px var(--ms-shadow-color);
}

.ms-cinema--flat {
  --ms-cinema-fg: var(--primaryTextColor);
  --ms-cinema-fg-dim: var(--secondaryTextColor);
  --ms-cinema-line: color-mix(in srgb, var(--primaryTextColor) 16%, transparent);
  --ms-cinema-fill: color-mix(in srgb, var(--primaryTextColor) 8%, transparent);
  --ms-cinema-fill-hover: color-mix(in srgb, var(--primaryTextColor) 16%, transparent);
  --ms-cinema-track: color-mix(in srgb, var(--primaryTextColor) 18%, transparent);
  --ms-cinema-title-shadow: none;
  --ms-cinema-cover-shadow: 0 22px 44px -18px var(--ms-shadow-color);
  background: transparent;
  border: 0;
  box-shadow: none;
}
.ms-cinema--flat .ms-cinema__inner {
  padding-top: 10px;
  padding-bottom: 96px;
}

.ms-cinema__bg {
  position: absolute;
  inset: 0;
  z-index: 0;
  background: var(--bg2);
}

.ms-cinema__bg-layer {
  position: absolute;
  inset: -10%;
  background-size: cover;
  background-position: center;
  filter: blur(46px) saturate(2.1) brightness(0.92);
  transform: scale(1.15);
  opacity: 0;
  transition: opacity 0.9s ease;
}
.ms-cinema__bg-layer.is-active {
  opacity: 1;
  animation: ms-cinema-drift 20s ease-in-out infinite alternate;
}

.ms-cinema__veil {
  position: absolute;
  inset: 0;
  background: radial-gradient(130% 130% at 50% 0%, rgba(0, 0, 0, 0) 0%, rgba(0, 0, 0, 0.34) 100%), linear-gradient(180deg, rgba(0, 0, 0, 0.18) 0%, rgba(0, 0, 0, 0.52) 100%);
}

.ms-cinema__swiper {
  position: relative;
  z-index: 1;
}

.ms-cinema__slide {
  height: auto;
}

.ms-cinema__inner {
  display: flex;
  flex-direction: row-reverse;
  align-items: center;
  justify-content: flex-start;
  gap: 46px;
  min-height: var(--ms-cinema-h);
  padding: 50px 56px 116px;
}

.ms-cinema__art {
  position: relative;
  flex: 0 0 auto;
  width: var(--ms-cinema-art);
  height: var(--ms-cinema-art);
  margin-inline-end: 34px;
}

.ms-cinema__disc {
  --ms-disc-size: calc(var(--ms-cinema-art) - 18px);
  position: absolute;
  top: 50%;
  inset-inline-end: 6px;
  z-index: 0;
  width: var(--ms-disc-size);
  height: var(--ms-disc-size);
  margin-top: calc(var(--ms-disc-size) / -2);
  border-radius: 50%;
  background: radial-gradient(circle at center, var(--primaryColor) 0 7%, rgba(0, 0, 0, 0.9) 7% 9.5%, transparent 9.5%), radial-gradient(circle at center, rgba(255, 255, 255, 0.16) 0 26%, transparent 26.5%), repeating-radial-gradient(circle at center, #26262e 0 1px, #0c0c10 1px 4px), #101015;
  box-shadow: 0 22px 46px -12px rgba(0, 0, 0, 0.85), inset 0 0 0 1px rgba(255, 255, 255, 0.1);
  opacity: 0;
  transform: scale(0.82);
  transition: inset-inline-end 0.8s cubic-bezier(0.2, 0.7, 0.3, 1), opacity 0.6s ease, transform 0.8s cubic-bezier(0.2, 0.7, 0.3, 1);
}
.ms-cinema__disc::after {
  content: "";
  position: absolute;
  inset: 0;
  border-radius: 50%;
  background: conic-gradient(from 0deg, rgba(255, 255, 255, 0) 0deg, rgba(255, 255, 255, 0.22) 40deg, rgba(255, 255, 255, 0) 90deg, rgba(255, 255, 255, 0) 180deg, rgba(255, 255, 255, 0.16) 220deg, rgba(255, 255, 255, 0) 280deg);
  mix-blend-mode: screen;
  pointer-events: none;
}

.swiper-slide-active .ms-cinema__disc {
  inset-inline-end: calc(var(--ms-cinema-art) / -4);
  opacity: 1;
  transform: scale(1);
  animation: ms-cinema-spin 6s linear infinite;
}

.ms-cinema__art:hover .ms-cinema__disc {
  inset-inline-end: calc(var(--ms-cinema-art) / -3.4);
  animation-duration: 2.4s;
}

.ms-cinema__cover {
  position: relative;
  z-index: 1;
  display: block;
  width: 100%;
  height: 100%;
  border-radius: 22px;
  overflow: hidden;
  box-shadow: var(--ms-cinema-cover-shadow), inset 0 0 0 1px rgba(255, 255, 255, 0.09);
}
.ms-cinema__cover img {
  width: 100%;
  height: 100%;
  object-fit: cover;
  transition: transform 0.6s cubic-bezier(0.2, 0.7, 0.3, 1);
}
.ms-cinema__cover:hover img {
  transform: scale(1.06);
}

.ms-cinema__disc-play {
  position: absolute;
  z-index: 2;
  top: 50%;
  left: 50%;
  display: flex;
  align-items: center;
  justify-content: center;
  width: 76px;
  height: 76px;
  border-radius: 50%;
  background: var(--primaryColor);
  color: var(--primaryTextBtn);
  font-size: 36px;
  line-height: 0;
  cursor: pointer;
  opacity: 0;
  transform: translate(-50%, -50%) scale(0.86);
  box-shadow: 0 0 0 10px var(--ms-cinema-fill), 0 16px 32px rgba(0, 0, 0, 0.5);
  transition: opacity 0.35s ease, transform 0.35s cubic-bezier(0.2, 0.7, 0.3, 1);
}

.ms-cinema__art:hover .ms-cinema__disc-play,
.ms-cinema__disc-play[data-state=playing],
.ms-cinema__disc-play[data-state=paused] {
  opacity: 1;
  transform: translate(-50%, -50%) scale(1);
}

.ms-cinema__content {
  flex: 1 1 auto;
  min-width: 0;
  color: var(--ms-cinema-fg);
}

.ms-cinema__eyebrow {
  display: inline-flex;
  align-items: center;
  gap: 9px;
  padding: 6px 15px;
  border-radius: 999px;
  border: 1px solid var(--ms-cinema-line);
  background: var(--ms-cinema-fill);
  backdrop-filter: blur(10px);
  font-size: 12px;
  font-weight: 400;
  color: var(--ms-cinema-fg);
}

.ms-cinema__eq {
  display: inline-flex;
  align-items: flex-end;
  gap: 2px;
  height: 13px;
}
.ms-cinema__eq i {
  width: 3px;
  height: 5px;
  border-radius: 2px;
  background: var(--primaryColor);
  animation: ms-cinema-eq 0.9s ease-in-out infinite;
}
.ms-cinema__eq i:nth-child(2) {
  animation-delay: 0.15s;
}
.ms-cinema__eq i:nth-child(3) {
  animation-delay: 0.3s;
}
.ms-cinema__eq i:nth-child(4) {
  animation-delay: 0.45s;
}

.ms-cinema__title {
  margin: 18px 0 8px;
  max-width: 640px;
  font-size: 40px;
  line-height: 1.3;
  font-weight: 700;
}
.ms-cinema__title a {
  color: var(--ms-cinema-fg);
  text-shadow: var(--ms-cinema-title-shadow);
  transition: color 0.3s;
}
.ms-cinema__title a:hover {
  color: var(--primaryColor);
}

.ms-cinema__artist {
  margin: 0 0 16px;
  font-size: 17px;
  font-weight: 200;
  color: var(--ms-cinema-fg-dim);
}

.ms-cinema__meta {
  display: flex;
  flex-wrap: wrap;
  gap: 8px;
  max-width: 640px;
  margin-bottom: 26px;
}

.ms-cinema__chip {
  display: inline-flex;
  align-items: center;
  flex-wrap: wrap;
  gap: 6px;
  max-width: 100%;
  min-width: 0;
  padding: 5px 13px;
  border-radius: 999px;
  border: 1px solid var(--ms-cinema-line);
  background: var(--ms-cinema-fill);
  font-size: 12px;
  font-weight: 200;
  color: var(--ms-cinema-fg-dim);
}
.ms-cinema__chip i {
  flex: 0 0 auto;
  font-size: 13px;
  color: var(--primaryColor);
}
.ms-cinema__chip a {
  color: inherit;
  white-space: nowrap;
}
.ms-cinema__chip a:hover {
  color: var(--primaryColor);
}

.ms-cinema__actions {
  display: flex;
  flex-wrap: wrap;
  align-items: center;
  gap: 12px;
}

.ms-cinema__btn {
  display: inline-flex;
  align-items: center;
  justify-content: center;
  gap: 8px;
  height: 48px;
  padding: 0 26px;
  border: 0;
  border-radius: 999px;
  font-size: 15px;
  font-weight: 400;
  cursor: pointer;
  transition: all 0.3s cubic-bezier(0.2, 0.7, 0.3, 1);
}

.ms-cinema__btn--play {
  background: linear-gradient(135deg, var(--primaryColor), var(--secondaryColor));
  color: var(--primaryTextBtn);
}
.ms-cinema__btn--play i {
  font-size: 22px;
  line-height: 0;
}
.ms-cinema__btn--play:hover {
  transform: translateY(-2px);
  filter: brightness(1.08);
}

.ms-cinema__btn--ghost {
  border: 1px solid var(--ms-cinema-line);
  background: var(--ms-cinema-fill);
  backdrop-filter: blur(10px);
  color: var(--ms-cinema-fg);
}
.ms-cinema__btn--ghost i {
  font-size: 17px;
  line-height: 0;
}
.ms-cinema__btn--ghost:hover {
  background: var(--ms-cinema-fill-hover);
  color: var(--ms-cinema-fg);
  transform: translateY(-2px);
}

.ms-cinema__save .ms-add-to-playlist {
  display: inline-flex;
  align-items: center;
  justify-content: center;
  width: 48px;
  height: 48px;
  padding: 0;
  border: 1px solid var(--ms-cinema-line);
  border-radius: 50%;
  background: var(--ms-cinema-fill);
  backdrop-filter: blur(10px);
  color: var(--ms-cinema-fg);
  transition: all 0.3s;
}
.ms-cinema__save .ms-add-to-playlist:hover {
  background: var(--ms-cinema-fill-hover);
  transform: translateY(-2px);
}
.ms-cinema__save .ms-add-to-playlist .ms-add-to-playlist__icon {
  font-size: 19px;
  line-height: 0;
}
.ms-cinema__save .ms-add-to-playlist .ms-add-to-playlist__text {
  display: none;
}

.ms-cinema__swiper.swiper-initialized .ms-cinema__content > * {
  opacity: 0;
  transform: translateY(28px);
}
.ms-cinema__swiper.swiper-initialized .swiper-slide-active .ms-cinema__content > * {
  animation: ms-cinema-in 0.7s cubic-bezier(0.2, 0.7, 0.3, 1) forwards;
}
.ms-cinema__swiper.swiper-initialized .swiper-slide-active .ms-cinema__content > *:nth-child(2) {
  animation-delay: 0.09s;
}
.ms-cinema__swiper.swiper-initialized .swiper-slide-active .ms-cinema__content > *:nth-child(3) {
  animation-delay: 0.18s;
}
.ms-cinema__swiper.swiper-initialized .swiper-slide-active .ms-cinema__content > *:nth-child(4) {
  animation-delay: 0.27s;
}
.ms-cinema__swiper.swiper-initialized .swiper-slide-active .ms-cinema__content > *:nth-child(5) {
  animation-delay: 0.36s;
}

.ms-cinema__controls {
  position: absolute;
  z-index: 3;
  bottom: 26px;
  left: 40px;
  right: 40px;
  display: flex;
  align-items: center;
  justify-content: space-between;
  gap: 18px;
  pointer-events: none;
}
.ms-cinema__controls > * {
  pointer-events: auto;
}

.ms-cinema__thumbs {
  display: flex;
  gap: 10px;
  max-width: 100%;
  overflow-x: auto;
  padding: 6px 2px;
  scrollbar-width: none;
}
.ms-cinema__thumbs::-webkit-scrollbar {
  display: none;
}

.ms-cinema__thumb {
  position: relative;
  flex: 0 0 auto;
  width: 58px;
  height: 58px;
  padding: 0;
  border: 0;
  border-radius: 15px;
  overflow: hidden;
  background: none;
  cursor: pointer;
  opacity: 0.42;
  transition: all 0.35s cubic-bezier(0.2, 0.7, 0.3, 1);
}
.ms-cinema__thumb img {
  width: 100%;
  height: 100%;
  object-fit: cover;
  display: block;
}
.ms-cinema__thumb:hover {
  opacity: 0.85;
  transform: translateY(-3px);
}
.ms-cinema__thumb.is-active {
  opacity: 1;
  transform: translateY(-4px);
  box-shadow: 0 0 0 2px var(--primaryColor), 0 12px 22px -10px rgba(0, 0, 0, 0.8);
}

.ms-cinema__thumb-progress {
  position: absolute;
  left: 0;
  right: 0;
  bottom: 0;
  height: 3px;
  background: var(--ms-cinema-track);
  opacity: 0;
}
.ms-cinema__thumb-progress i {
  display: block;
  width: 0;
  height: 100%;
  background: var(--primaryColor);
}

.ms-cinema__thumb.is-active .ms-cinema__thumb-progress {
  opacity: 1;
}

.ms-cinema.is-autoplay .ms-cinema__thumb.is-active .ms-cinema__thumb-progress i {
  animation: ms-cinema-progress var(--ms-cinema-delay) linear forwards;
}

.ms-cinema.is-autoplay.is-paused .ms-cinema__thumb.is-active .ms-cinema__thumb-progress i {
  animation-play-state: paused;
}

.ms-cinema__nav {
  display: flex;
  align-items: center;
  gap: 10px;
}

.ms-cinema__count {
  margin-inline-end: 4px;
  font-size: 13px;
  font-weight: 200;
  color: var(--ms-cinema-fg-dim);
  white-space: nowrap;
}
.ms-cinema__count b {
  font-weight: 600;
  color: var(--ms-cinema-fg);
}

.ms-cinema__arrow {
  display: flex;
  align-items: center;
  justify-content: center;
  width: 44px;
  height: 44px;
  padding: 0;
  border: 1px solid var(--ms-cinema-line);
  border-radius: 14px;
  background: var(--ms-cinema-fill);
  backdrop-filter: blur(10px);
  color: var(--ms-cinema-fg);
  font-size: 17px;
  line-height: 0;
  cursor: pointer;
  transition: all 0.3s;
}
.ms-cinema__arrow:hover {
  background: var(--primaryColor);
  border-color: transparent;
  color: var(--primaryTextBtn);
}
.ms-cinema__arrow.swiper-button-disabled {
  opacity: 0.35;
  cursor: default;
}

.ms-cinema--single .ms-cinema__inner {
  padding-bottom: 50px;
}

html.light .ms-cinema__cover img {
  border-radius: 0 !important;
}

html.light .ms-cinema:not(.ms-cinema--flat) {
  --ms-cinema-cover-shadow: 0 26px 50px -18px rgba(0, 0, 0, 0.55);
  box-shadow: 0 24px 50px -32px var(--ms-shadow-color);
}

html.light .ms-cinema--flat .ms-cinema__disc {
  box-shadow: 0 18px 36px -16px var(--ms-shadow-color), inset 0 0 0 1px rgba(255, 255, 255, 0.14);
}
html.light .ms-cinema--flat .ms-cinema__disc-play {
  box-shadow: 0 0 0 10px color-mix(in srgb, var(--ms-white) 65%, transparent), 0 16px 32px -10px var(--ms-shadow-color);
}

@keyframes ms-cinema-in {
  to {
    opacity: 1;
    transform: translateY(0);
  }
}
@keyframes ms-cinema-spin {
  to {
    transform: rotate(360deg);
  }
}
@keyframes ms-cinema-eq {
  0%, 100% {
    height: 4px;
  }
  50% {
    height: 13px;
  }
}
@keyframes ms-cinema-progress {
  from {
    width: 0;
  }
  to {
    width: 100%;
  }
}
@keyframes ms-cinema-drift {
  from {
    transform: scale(1.15) translate3d(0, 0, 0);
  }
  to {
    transform: scale(1.24) translate3d(-2%, -2%, 0);
  }
}
@media screen and (max-width: 1200px) {
  .ms-cinema {
    --ms-cinema-h: 430px;
    --ms-cinema-art: 250px;
  }

  .ms-cinema__inner {
    gap: 34px;
    padding: 44px 38px 108px;
  }

  .ms-cinema__title {
    font-size: 32px;
  }
}
@media screen and (max-width: 960px) {
  .ms-cinema {
    --ms-cinema-h: auto;
    --ms-cinema-art: 210px;
    --ms-cinema-radius: 20px;
    margin: 20px 0 40px;
  }

  .ms-cinema__inner {
    flex-direction: column;
    align-items: center;
    justify-content: center;
    text-align: center;
    gap: 26px;
    padding: 36px 22px 104px;
  }

  .ms-cinema__art {
    margin-inline-end: 0;
  }

  .ms-cinema__disc {
    display: none;
  }

  .ms-cinema__disc-play {
    opacity: 1;
    transform: translate(-50%, -50%) scale(1);
    width: 62px;
    height: 62px;
    font-size: 30px;
  }

  .ms-cinema__title,
.ms-cinema__meta {
    max-width: 100%;
  }

  .ms-cinema__title {
    font-size: 26px;
    margin-top: 14px;
  }

  .ms-cinema__artist {
    font-size: 15px;
  }

  .ms-cinema__meta,
.ms-cinema__actions {
    justify-content: center;
  }

  .ms-cinema__meta {
    margin-bottom: 20px;
  }

  .ms-cinema__nav {
    display: none;
  }

  .ms-cinema__controls {
    left: 0;
    right: 0;
    bottom: 16px;
    justify-content: center;
  }

  .ms-cinema__thumbs {
    max-width: 100%;
    justify-content: flex-start;
    padding: 6px 18px;
    scroll-snap-type: x proximity;
  }

  .ms-cinema__thumb {
    width: 46px;
    height: 46px;
    border-radius: 12px;
    scroll-snap-align: center;
  }
}
@media screen and (max-width: 575px) {
  .ms-cinema {
    --ms-cinema-art: 172px;
  }

  .ms-cinema__inner {
    gap: 20px;
    padding: 28px 16px 88px;
  }

  .ms-cinema__title {
    font-size: 21px;
    margin-top: 12px;
  }

  .ms-cinema__artist {
    font-size: 14px;
    margin-bottom: 12px;
  }

  .ms-cinema__chip--genre a:nth-of-type(n + 3) {
    display: none;
  }

  .ms-cinema__actions {
    gap: 8px;
  }

  .ms-cinema__btn {
    height: 44px;
    padding: 0 18px;
    font-size: 14px;
  }

  .ms-cinema__save .ms-add-to-playlist {
    width: 44px;
    height: 44px;
  }

  .ms-cinema__thumb {
    width: 40px;
    height: 40px;
    border-radius: 10px;
  }
}
@media (prefers-reduced-motion: reduce) {
  .ms-cinema__bg-layer.is-active,
.swiper-slide-active .ms-cinema__disc,
.ms-cinema__art:hover .ms-cinema__disc,
.ms-cinema__eq i {
    animation: none;
  }

  .ms-cinema__swiper.swiper-initialized .ms-cinema__content > * {
    opacity: 1;
    transform: none;
    animation: none;
  }
}
