  display: none;
  z-index: 9999;
  position: static;
  width: 100%;
}

.adminNotice_up {
  top: 0;
}

.adminNotice_down {
  position: fixed !important;
  bottom: 0;
}

.adminNotice .dismiss {
  font-size: 13px;
  color: #e9e9e9;
  margin-left: 5px;
  cursor: pointer;
  transition: all 0.3s;
}

.adminNotice .dismiss:hover {
  color: var(--ms-white);
}

.adminNotice span {
  font-size: 15px;
  color: #f9f9f9;
  font-weight: 500;
  text-shadow: 0 0 3px #000000b8;
}

.adminNotice .adminNotice__btn a {
  color: #101014;
  background: var(--ms-white);
  padding: 6px 15px;
