/* =====================================================================
   Sticky player — redesigned bar, waveform seek & mini bubble
   ================================================================== */
#player {
  --ms-wave-pos: 0%;
  --ms-wave-height: 30px;
  --ms-player-accent: var(--primaryColor);
  --ms-player-muted: #9aa6ba;
  --ms-player-hover: rgba(255, 255, 255, .09);
  --ms-wave-idle: rgba(255, 255, 255, .24);
  --plyr-color-main: var(--primaryColor);
  overflow: visible;
}
#player > .container,
#player > .container-fluid,
#player > .container-sm,
#player > .container-md,
#player > .container-lg,
#player > .container-xl,
#player > .container-xxl {
  max-width: 100%;
  padding-left: 14px;
  padding-right: 14px;
}
#player .plyr {
  min-width: 0;
}

/* --- layout ------------------------------------------------------- */
#player .ms-player-bar {
  display: grid;
  grid-template-columns: auto minmax(0, 1fr) auto;
  align-items: center;
  gap: 14px;
  padding: 9px 0 !important;
  background: transparent;
}

#player .ms-player-bar__meta {
  display: flex;
  align-items: center;
  gap: 10px;
  min-width: 0;
  max-width: 260px;
}

#player .ms-player-bar__main {
  display: grid;
  gap: 4px;
  min-width: 0;
}

#player .ms-player-bar__tools {
  display: flex;
  align-items: center;
  justify-content: flex-start;
  gap: 2px;
}

/* --- artwork ------------------------------------------------------ */
#player .ms-player-art {
  position: relative;
  flex: 0 0 auto;
  width: 46px;
  height: 46px;
  border-radius: 13px;
  overflow: hidden;
  display: grid;
  place-items: center;
  background: linear-gradient(140deg, rgba(255, 255, 255, 0.16), rgba(255, 255, 255, 0.04));
  box-shadow: 0 6px 16px -8px rgba(0, 0, 0, 0.8);
}
#player .ms-player-art__img {
  display: none;
  width: 100%;
  height: 100%;
  object-fit: cover;
}
#player .ms-player-art__placeholder {
  font-size: 18px;
  line-height: 0;
  color: var(--ms-player-muted);
}
#player .ms-player-art.has-art .ms-player-art__img {
  display: block;
}
#player .ms-player-art.has-art .ms-player-art__placeholder {
  display: none;
}
#player .ms-player-art__eq {
  position: absolute;
  inset: 0;
  display: none;
  align-items: flex-end;
  justify-content: center;
  gap: 2px;
  padding-bottom: 8px;
  background: rgba(0, 0, 0, 0.38);
}
#player .ms-player-art__eq i {
  display: block;
  width: 3px;
  height: 7px;
  border-radius: 2px;
  background: var(--ms-white);
  transform-origin: bottom;
}

#player.ms-player--no-art .ms-player-art {
  display: none;
}

#player.is-playing .ms-player-art__eq {
  display: flex;
}

#player.is-playing:not(.ms-player--wave-static) .ms-player-art__eq i {
  animation: msPlayerEq 0.9s ease-in-out infinite;
}
#player.is-playing:not(.ms-player--wave-static) .ms-player-art__eq i:nth-child(2) {
  animation-delay: -0.18s;
}
#player.is-playing:not(.ms-player--wave-static) .ms-player-art__eq i:nth-child(3) {
  animation-delay: -0.36s;
}
#player.is-playing:not(.ms-player--wave-static) .ms-player-art__eq i:nth-child(4) {
  animation-delay: -0.54s;
}

@keyframes msPlayerEq {
  0%, 100% {
    transform: scaleY(0.5);
  }
  50% {
    transform: scaleY(2.1);
  }
}
/* --- track meta --------------------------------------------------- */
#player .ms-player-meta {
  display: grid;
  gap: 2px;
  min-width: 0;
}
#player .ms-player-meta__sub {
  font-size: 11px;
  line-height: 1.5;
  color: var(--ms-player-muted);
  white-space: nowrap;
  overflow: hidden;
  text-overflow: ellipsis;
}
#player .ms-player-meta__sub:empty {
  display: none;
}

#player .song_name {
  display: block;
  font-size: 13px;
  font-weight: 700;
  line-height: 1.5;
  color: var(--primaryTextColor);
  white-space: nowrap;
  overflow: hidden;
  text-overflow: ellipsis;
}

/* --- transport buttons -------------------------------------------- */
#player .ms-player-buttons {
  display: flex;
  align-items: center;
  justify-content: center;
  gap: 4px;
}

#player .ms-player-buttons .plyr__control {
  color: var(--primaryTextColor);
  background: transparent;
  border-radius: 50%;
  padding: 7px;
  margin: 0;
  transition: background 0.2s ease, transform 0.2s ease, color 0.2s ease;
}
#player .ms-player-buttons .plyr__control:hover {
  background: var(--ms-player-hover) !important;
  color: var(--primaryTextColor) !important;
}
#player .ms-player-buttons .plyr__control:active {
  transform: scale(0.94);
}

#player .ms-player-buttons .play_button {
  width: 42px;
  height: 42px;
  padding: 0 !important;
  display: grid;
  place-items: center;
  background: var(--primaryColor) !important;
  color: var(--ms-white) !important;
  box-shadow: 0 8px 20px -8px var(--primaryColor);
}
#player .ms-player-buttons .play_button svg {
  width: 15px;
  height: 15px;
}
#player .ms-player-buttons .play_button:hover {
  background: var(--primaryColor) !important;
  color: var(--ms-white) !important;
  transform: scale(1.06);
}

/* --- seek row ----------------------------------------------------- */
#player .ms-player-seek {
  display: flex;
  align-items: center;
  gap: 10px;
  direction: ltr;
}
#player .ms-player-seek .plyr__time {
  flex: 0 0 auto;
  min-width: 38px;
  font-size: 11px;
  line-height: 1.4;
  color: var(--ms-player-muted);
  font-variant-numeric: tabular-nums;
  text-align: center;
  margin: 0 !important;
  padding: 0 !important;
}
#player .ms-player-seek .plyr__progress__container {
  flex: 1 1 auto;
  min-width: 0;
  padding: 0 !important;
}

#player .plyr__progress {
  position: relative;
  left: 0 !important;
  margin: 0 !important;
  height: var(--ms-wave-height);
  display: flex;
  align-items: center;
}
#player .plyr__progress .plyr__progress__buffer {
  display: none;
}
#player .plyr__progress .plyr__tooltip {
  z-index: 8;
}

#player .plyr__progress input[type=range] {
  position: absolute;
  inset: 0;
  width: 100% !important;
  height: 100% !important;
  margin: 0 !important;
  padding: 0;
  opacity: 0;
  z-index: 5;
  cursor: pointer;
}

/* Plain line style keeps the native plyr track, just tidied up. */
#player[data-wave-style=line] {
  --ms-wave-height: 20px;
}
#player[data-wave-style=line] .plyr__progress input[type=range] {
  opacity: 1;
  --plyr-range-track-height: 5px;
  --plyr-range-thumb-height: 12px;
}

/* --- waveform ----------------------------------------------------- */
#player .ms-wave {
  position: absolute;
  inset: 0;
  z-index: 2;
  pointer-events: none;
  overflow: hidden;
  border-radius: 4px;
}
#player .ms-wave__layer {
  position: absolute;
  inset: 0;
  display: flex;
  align-items: flex-end;
  gap: var(--ms-wave-gap, 2px);
  height: 100%;
}
#player .ms-wave__layer--bg {
  color: var(--ms-wave-idle);
}
#player .ms-wave__layer--fill {
  color: var(--ms-player-accent);
  clip-path: inset(0 calc(100% - var(--ms-wave-pos)) 0 0);
}
#player .ms-wave__bar {
  flex: 1 1 0;
  min-width: 0;
  height: var(--h, 50%);
  border-radius: 2px;
  background: currentColor;
  transform-origin: bottom center;
}
#player .ms-wave__svg {
  width: 100%;
  height: 100%;
  display: block;
}
#player .ms-wave__svg path {
  fill: currentColor;
}
#player .ms-wave__head {
  position: absolute;
  top: 50%;
  left: var(--ms-wave-pos);
  width: 2px;
  height: 100%;
  border-radius: 2px;
  background: var(--ms-white);
  box-shadow: 0 0 10px rgba(255, 255, 255, 0.55);
  transform: translate(-50%, -50%);
  opacity: 0;
  transition: opacity 0.2s ease;
}

#player[data-wave-style=mirror] .ms-wave__layer {
  align-items: center;
}

#player[data-wave-style=mirror] .ms-wave__bar {
  transform-origin: center;
}

#player.is-playing .ms-wave__head,
#player .plyr__progress:hover .ms-wave__head {
  opacity: 0.85;
}

#player.is-playing:not(.ms-player--wave-static) .ms-wave__bar {
  animation: msWaveBar 1.7s ease-in-out infinite;
  animation-delay: calc(var(--i, 0) * var(--ms-wave-step, -30ms));
}

#player.is-playing:not(.ms-player--wave-static)[data-wave-style=wave] .ms-wave__svg {
  animation: msWaveBreathe 2.8s ease-in-out infinite;
  transform-origin: center;
}

@keyframes msWaveBar {
  0%, 100% {
    transform: scaleY(0.87);
  }
  50% {
    transform: scaleY(1.1);
  }
}
@keyframes msWaveBreathe {
  0%, 100% {
    transform: scaleY(0.88);
  }
  50% {
    transform: scaleY(1.05);
  }
}
@media (prefers-reduced-motion: reduce) {
  #player .ms-wave__bar,
#player .ms-wave__svg,
#player .ms-player-art__eq i {
    animation: none !important;
  }
}
/* --- tools cluster ------------------------------------------------ */
#player .ms-player-bar__tools .plyr__control {
  width: 34px;
  height: 34px;
  min-width: 34px;
  min-height: 34px;
  padding: 0;
  margin: 0;
  display: grid;
  place-items: center;
  border-radius: 11px;
  color: var(--ms-player-muted);
  background: transparent;
  transition: background 0.2s ease, color 0.2s ease;
}
#player .ms-player-bar__tools .plyr__control i {
  font-size: 15px;
  line-height: 1;
}
#player .ms-player-bar__tools .plyr__control:hover {
  background: var(--ms-player-hover) !important;
  color: var(--primaryTextColor) !important;
}

#player .custom_queue_toggle {
  color: var(--primaryColor) !important;
}

#player.ms-queue-open .custom_queue_toggle {
  background: var(--primaryColorLight) !important;
}

#player .ms-player-minimize i {
  font-size: 17px;
}

#player .ms-player-stop:hover {
  color: var(--primaryColor) !important;
}

#player .plyr__volume {
  min-width: auto;
  max-width: none;
  width: auto;
  margin: 0 2px;
}
#player .plyr__volume input[type=range] {
  width: 66px;
  max-width: 66px;
  margin-left: 2px;
}
#player .plyr__volume .plyr__control {
  color: var(--ms-player-muted);
  padding: 6px;
}

/* --- mini bubble -------------------------------------------------- */
#open_player {
  --ms-wave-pos: 0%;
  position: fixed;
  z-index: 999;
  bottom: 16px;
  right: 18px;
  display: none;
  align-items: center;
  gap: 9px;
  max-width: min(320px, 100vw - 32px);
  padding: 6px;
  border-radius: 999px;
  background: rgba(24, 25, 32, 0.74);
  backdrop-filter: blur(28px) saturate(180%);
  border: 1px solid rgba(255, 255, 255, 0.12);
  box-shadow: 0 18px 42px -18px rgba(0, 0, 0, 0.85);
  color: var(--primaryTextColor);
  cursor: pointer;
  transition: transform 0.25s ease, box-shadow 0.25s ease;
}
#open_player:hover {
  transform: translateY(-2px);
  box-shadow: 0 22px 46px -18px rgba(0, 0, 0, 0.9);
}
#open_player.is-visible {
  animation: msMiniIn 0.32s cubic-bezier(0.2, 0.8, 0.3, 1) both;
}
#open_player .ms-mini__art {
  position: relative;
  flex: 0 0 auto;
  width: 42px;
  height: 42px;
  padding: 2px;
  border-radius: 50%;
  display: grid;
  place-items: center;
  background: conic-gradient(var(--primaryColor) var(--ms-wave-pos), rgba(255, 255, 255, 0.16) 0);
}
#open_player .ms-mini__art::after {
  content: "";
  position: absolute;
  inset: 2px;
  border-radius: 50%;
  background: rgba(20, 21, 27, 0.92);
}
#open_player .ms-mini__img {
  position: relative;
  z-index: 2;
  display: none;
  width: 100%;
  height: 100%;
  border-radius: 50%;
  object-fit: cover;
}
#open_player .ms-mini__placeholder {
  position: relative;
  z-index: 2;
  font-size: 15px;
  line-height: 0;
  color: var(--ms-player-muted, #9aa6ba);
}
#open_player.has-art .ms-mini__img {
  display: block;
}
#open_player.has-art .ms-mini__placeholder {
  display: none;
}
#open_player.is-playing .ms-mini__img {
  animation: msMiniSpin 10s linear infinite;
}
#open_player .ms-mini__body {
  display: grid;
  gap: 1px;
  min-width: 0;
  max-width: 148px;
  text-align: start;
}
#open_player .ms-mini__title {
  font-size: 12px;
  font-weight: 700;
  line-height: 1.5;
  white-space: nowrap;
  overflow: hidden;
  text-overflow: ellipsis;
}
#open_player .ms-mini__sub {
  font-size: 10px;
  line-height: 1.5;
  color: var(--secondaryTextColor);
  white-space: nowrap;
  overflow: hidden;
  text-overflow: ellipsis;
}
#open_player .ms-mini__btn {
  flex: 0 0 auto;
  width: 30px;
  height: 30px;
  padding: 0;
  border: 0;
  border-radius: 50%;
  display: grid;
  place-items: center;
  line-height: 0;
  font-size: 15px;
  background: transparent;
  color: var(--primaryTextColor);
  transition: background 0.2s ease, color 0.2s ease, transform 0.2s ease;
}
#open_player .ms-mini__btn:hover {
  background: rgba(255, 255, 255, 0.12);
}
#open_player .ms-mini__btn:active {
  transform: scale(0.92);
}
#open_player .ms-mini__play {
  background: var(--primaryColor);
  color: var(--ms-white);
  font-size: 17px;
  box-shadow: 0 6px 16px -6px var(--primaryColor);
}
#open_player .ms-mini__play:hover {
  background: var(--primaryColor);
}
#open_player .ms-mini__close {
  font-size: 16px;
  color: var(--secondaryTextColor);
}
#open_player .ms-mini__close:hover {
  color: var(--primaryColor);
}

@keyframes msMiniIn {
  from {
    opacity: 0;
    transform: translateY(14px) scale(0.94);
  }
  to {
    opacity: 1;
    transform: translateY(0) scale(1);
  }
}
@keyframes msMiniSpin {
  to {
    transform: rotate(360deg);
  }
}
@media (prefers-reduced-motion: reduce) {
  #open_player.is-playing .ms-mini__img,
#open_player.is-visible {
    animation: none !important;
  }
}
/* --- responsive --------------------------------------------------- */
@media screen and (max-width: 991px) {
  #player .ms-player-bar {
    grid-template-columns: minmax(0, 1fr) auto;
    grid-template-areas: "meta tools" "main main";
    row-gap: 4px;
  }

  #player .ms-player-bar__meta {
    grid-area: meta;
  }

  #player .ms-player-bar__main {
    grid-area: main;
  }

  #player .ms-player-bar__tools {
    grid-area: tools;
  }
}
@media screen and (max-width: 767px) {
  #player {
    --ms-wave-height: 24px;
  }
  #player > .container,
#player > .container-fluid,
#player > .container-sm,
#player > .container-md,
#player > .container-lg,
#player > .container-xl,
#player > .container-xxl {
    padding-left: 10px;
    padding-right: 10px;
  }
  #player .ms-player-art {
    width: 40px;
    height: 40px;
    border-radius: 11px;
  }
  #player .play_button {
    width: 38px;
    height: 38px;
  }
  #player .ms-player-bar__tools .plyr__control {
    width: 32px;
    height: 32px;
    min-width: 32px;
    min-height: 32px;
  }

  #open_player {
    right: 12px;
    bottom: 12px;
  }
}
@media screen and (max-width: 500px) {
  #player .ms-player-seek .plyr__time {
    min-width: 34px;
    font-size: 10px;
  }

  #open_player .ms-mini__body {
    display: none;
  }
}
/* --- light theme -------------------------------------------------- */
html.light #player {
  --ms-player-muted: #5d6a80;
  --ms-player-hover: rgba(36, 50, 71, .08);
  --ms-wave-idle: rgba(36, 50, 71, .22);
}
html.light #player .ms-player-art {
  background: linear-gradient(140deg, rgba(36, 50, 71, 0.12), rgba(36, 50, 71, 0.04));
  box-shadow: 0 6px 16px -10px rgba(43, 52, 69, 0.5);
}
html.light #player .ms-wave__head {
  background: #243247;
  box-shadow: 0 0 10px rgba(36, 50, 71, 0.35);
}
html.light #player .ms-player-buttons .plyr__control {
  color: var(--primaryTextColor);
}
html.light #open_player {
  background: rgba(255, 255, 255, 0.82);
  border-color: rgba(36, 50, 71, 0.12);
  box-shadow: 0 18px 40px -20px rgba(43, 52, 69, 0.45);
  color: #243247;
}
html.light #open_player .ms-mini__art::after {
  background: #ffffff;
}
html.light #open_player .ms-mini__btn {
  color: #243247;
}
html.light #open_player .ms-mini__btn:hover {
  background: rgba(36, 50, 71, 0.1);
}
html.light #open_player .ms-mini__play {
  color: var(--ms-white);
}
html.light #open_player .ms-mini__sub,
html.light #open_player .ms-mini__placeholder {
  color: #5d6a80;
}

