html {
  font-size: $baseFontSize;
}

body {
  background: var(--ms-body-bg);
  font-family: $baseFont;
  font-size: $baseFontSize;
}

a {
  color: var(--primaryTextColor);
  transition: all .2s;
  &:hover{
    color: var(--primaryColor);
  }
}

ul,
ol {
  padding: 0;
  margin: 0;
}

.header{
  padding: 25px 0;
  background: color-mix(in srgb, var(--ms-header-bg) 70%, transparent);
  box-shadow: 0 10px 25px var(--ms-shadow-color);
  backdrop-filter: blur(12px);
  -webkit-backdrop-filter: blur(12px);
  transition: all .3s;
  &.fixed{
    background: color-mix(in srgb, var(--ms-header-sticky-bg) 70%, transparent);
  }
  &.stick_header{
    position: sticky;
    top: 0;
    z-index: 99;
  }
  .logo{
    display: flex;
    align-items: center;
    gap: 10px;
    img{
      max-width: 40px;
      height: auto;
    }
    span{
      color: var(--primaryTextColor);
      font-size: 15px;
      font-weight: 800;
      margin: 0;
    }
  }
  .top_nav{
    ul{
      li{
        list-style: none;
        display: inline-block;
        margin-left: 10px;
        position: relative;
        &:hover .sub-menu{
          // display: block;
          opacity: 1;
          visibility: visible;
          top: 35px;
        }
        .sub-menu{
          &::before{
            border-color: transparent transparent #2c2b2b;
            border-style: solid;
            border-width: 0 5px 6px;
            content: "";
            height: 0;
            position: absolute;
            right: 11px;
            top: -6px;
            width: 0;
          }
          // display: none;
          opacity: 0;
          visibility: hidden;
          position: absolute;
          top: 50px;
          right: 0;
          width: 200px;
          z-index: 99;
          background: var(--ms-card-bg);
          padding: 10px;
          border-radius: $baseRadius;
          transition: all 0.2s;
          li{
            display: block;
            padding: 0;
            margin: 0;
            position: relative;
            &:hover .sub-menu{
              opacity: 1;
              visibility: visible;
            }
            .sub-menu{
              &::before{
                border-color: transparent transparent #2c2b2b;
                border-style: solid;
                border-width: 0 5px 6px;
                content: "";
                height: 0;
                position: absolute;
                right: -8px;
                top: 15px;
                width: 0;
                transform: rotate(90deg);
            }
              top: 0px;
              opacity: 0;
              visibility: hidden;
              position: absolute;
              right: 200px;

              li{
                &:hover .sub-menu{
                  opacity: 1;
                  visibility: visible;
                }
                .sub-menu{
                  &::before{
                    border-color: transparent transparent #2c2b2b;
                    border-style: solid;
                    border-width: 0 5px 6px;
                    content: "";
                    height: 0;
                    position: absolute;
                    right: -8px;
                    top: 15px;
                    width: 0;
                    transform: rotate(90deg);
                  }
                  top: 0px;
                  opacity: 0;
                  visibility: hidden;
                  position: absolute;
                  right: 200px;

                  li{
                    &:hover .sub-menu{
                      opacity: 1;
                      visibility: visible;
                    }
                    .sub-menu{
                      &::before{
                        border-color: transparent transparent #2c2b2b;
                        border-style: solid;
                        border-width: 0 5px 6px;
                        content: "";
                        height: 0;
                        position: absolute;
                        right: -8px;
                        top: 15px;
                        width: 0;
                        transform: rotate(90deg);
                      }
                      top: 0px;
                      opacity: 0;
                      visibility: hidden;
                      position: absolute;
                      right: 200px;
                    }
                  }
                }
              }
            }
            a{
              padding: 5px 10px;
              border-radius: $baseRadius;
              display: block;
              transition: all 0.2s;
              font-size: 13px;
              &:hover{
                background: var(--primaryColor);
                color: var(--primaryTextBtn);
              }
            }
          }
        }
      }
    }
    a{
      padding: 3px;
    }
  }


  }
  .leftSide{
    align-items: center;
    gap: 8px;
    .search_mobile{
      display: none;
      button{
        background: none;
        border: none;
        outline: none;
        color: var(--primaryTextColor);
        font-size: 20px;
        line-height: 0;
        padding: 0;
      }
    }
    .light_switch{
      line-height: 0;
      margin-left: 0;
      button{
        background: linear-gradient(160deg, color-mix(in srgb, var(--primaryColor) 18%, transparent), color-mix(in srgb, var(--secondaryColor) 14%, transparent));
        color: var(--primaryTextColor);
        border: 1px solid color-mix(in srgb, var(--primaryColor) 35%, transparent);
        font-size: 16px;
        line-height: 0;
        outline: none;
        width: 43px;
        height: 43px;
        display: flex;
        justify-content: center;
        align-items: center;
        border-radius: .75rem;
        transition: transform .2s ease, box-shadow .2s ease, border-color .2s ease;
        &:hover{
          transform: translateY(-1px);
          border-color: color-mix(in srgb, var(--primaryColor) 55%, transparent);
          box-shadow: 0 8px 18px color-mix(in srgb, var(--primaryColor) 22%, transparent);
        }
      }
    }
    .login_register{
      line-height: 0;
      margin-left: 0;
      position: relative;
      a, .account_trigger{
        background: linear-gradient(150deg, color-mix(in srgb, var(--primaryColor) 16%, transparent), color-mix(in srgb, var(--success) 12%, transparent));
        color: var(--primaryTextColor);
        border: 1px solid color-mix(in srgb, var(--primaryColor) 35%, transparent);
        font-size: 16px;
        line-height: 0;
        outline: none;
        width: 43px;
        height: 43px;
        display: flex;
        justify-content: center;
        align-items: center;
        border-radius: .75rem;
        padding: 0;
        transition: transform .2s ease, box-shadow .2s ease, border-color .2s ease;
        &:hover{
          transform: translateY(-1px);
          border-color: color-mix(in srgb, var(--primaryColor) 55%, transparent);
          box-shadow: 0 8px 18px color-mix(in srgb, var(--primaryColor) 24%, transparent);
        }
        i{
          font-size: 18px;
        }
      }
      .account_trigger{
        &::after{
          display: none;
        }
        .quick_avatar{
          width: 32px;
          height: 32px;
          border-radius: 50%;
          overflow: hidden;
          display: flex;
          align-items: center;
          justify-content: center;
          img, .avatar{
            width: 100%;
            height: 100%;
            object-fit: cover;
            border-radius: 50%;
          }
        }
      }
      .quick_access_menu{
        position: absolute;
        top: calc(100% + 10px);
        left: 0;
        z-index: 30;
        width: 280px;
        border: 1px solid var(--borderColor);
        border-radius: 12px;
        background: var(--postBgColor);
        box-shadow: 0 8px 35px rgba(0, 0, 0, 0.24);
        padding: 12px;
        opacity: 0;
        visibility: hidden;
        pointer-events: none;
        transform: translateY(8px) scale(.98);
        transform-origin: top center;
        transition: opacity .22s ease, transform .22s ease, visibility .22s ease;

        .quick_access_days{
          display: flex;
          color: var(--ms-white);
          margin-right: auto;
          background: #4CAF50;
          width: auto;
          height: 34px;
          justify-content: center;
