.music_card.music_card_poster{
  position: relative;
  padding: 0;
  overflow: hidden;
  border-radius: 16px;
  isolation: isolate;
  transition: transform .45s cubic-bezier(.2,.8,.3,1), box-shadow .45s ease;

  // gradient hairline that lights up on hover
  &:before{
    content: "";
    position: absolute;
    inset: 0;
    z-index: 5;
    border-radius: inherit;
    padding: 1px;
    background: linear-gradient(140deg, var(--primaryColor), rgba(255,255,255,.35) 55%, transparent);
    -webkit-mask: linear-gradient(#fff 0 0) content-box, linear-gradient(#fff 0 0);
    mask: linear-gradient(#fff 0 0) content-box, linear-gradient(#fff 0 0);
    -webkit-mask-composite: xor;
    mask-composite: exclude;
    opacity: 0;
    pointer-events: none;
    transition: opacity .4s ease;
  }

  .swiper_image{
    margin-bottom: 0;
    overflow: hidden;
    border-radius: inherit;
    // only the cover link, never the download button that sits next to it
    > a:not(.dl_icon){
      display: block;
      border-radius: inherit;
    }
    img{
      display: block;
      width: 100%;
      aspect-ratio: 1 / 1;
      object-fit: cover;
      border-radius: inherit;
      transition: transform .6s cubic-bezier(.2,.8,.3,1);
    }
    .image_overlay{
      border-radius: inherit;
      z-index: 2;
    }
  }

  .music_card_poster__scrim{
    position: absolute;
    inset: 0;
    z-index: 1;
    border-radius: inherit;
    pointer-events: none;
    background: linear-gradient(to top, rgba(8,8,12,.94) 0%, rgba(8,8,12,.55) 42%, rgba(8,8,12,0) 72%);
    opacity: .9;
    transition: opacity .4s ease;
  }

  .swiper_title{
    position: absolute;
    inset-inline: 0;
    bottom: 0;
    z-index: 4;
    padding: 14px;
    transform: translateY(6px);
    transition: transform .4s cubic-bezier(.2,.8,.3,1);
    .music_card__title{
      color: var(--ms-white);
      font-size: 15px;
      font-weight: 700;
      margin-bottom: 4px;
      text-shadow: 0 2px 10px rgba(0,0,0,.65);
    }
    .swiper_artist{
      color: rgba(255,255,255,.72);
      font-size: 12px;
      a{
        color: rgba(255,255,255,.72);
        font-weight: 400;
      }
    }
  }

  .music_card__actions{
    opacity: 0;
    transition: opacity .3s ease;
    i, .ms-add-to-playlist{
      color: rgba(255,255,255,.85);
    }
  }

  .play_icon, .dl_icon{
    position: absolute;
    top: 50%;
    left: 50%;
    z-index: 4;
    width: 54px;
    height: 54px;
    margin: 0;
    border-radius: 50%;
    opacity: 0;
    transform: translate(-50%,-50%) scale(.6);
    background: var(--primaryColor);
    box-shadow: 0 14px 30px -8px var(--primaryColor);
    transition: opacity .35s ease, transform .35s cubic-bezier(.2,.8,.3,1);
    i{
      font-size: 28px;
    }
  }

  &:hover{
    transform: translateY(-6px);
    box-shadow: 0 22px 45px -20px rgba(0,0,0,.85);
    &:before{
      opacity: 1;
    }
    .swiper_image img{
      transform: scale(1.08);
    }
    .music_card_poster__scrim{
      opacity: 1;
    }
    .swiper_title{
      transform: translateY(0);
    }
    .music_card__actions{
      opacity: 1;
    }
    .play_icon, .dl_icon{
      opacity: 1;
      transform: translate(-50%,-50%) scale(1);
    }
    .play_icon:hover, .dl_icon:hover{
      transform: translate(-50%,-50%) scale(1.1);
    }
  }
}

// touch devices never get :hover, so keep the controls visible there
@media (hover: none){
  .music_card.music_card_poster{
    .play_icon, .dl_icon{
      opacity: 1;
      transform: translate(-50%,-50%) scale(1);
    }
    .music_card__actions{
      opacity: 1;
    }
    .swiper_title{
      transform: translateY(0);
    }
  }
}

