.footer.footer--minimal{
  background: transparent;
  overflow: hidden;
  padding: 0 20px 24px;
  .go_up{
    background: color-mix(in srgb, var(--primaryColor) 70%, #101015);
    box-shadow: 0 10px 28px color-mix(in srgb, var(--primaryColor) 28%, transparent);
    color: var(--primaryTextBtn);
    top: -23px;
  }
  .footer__wave{
    color: color-mix(in srgb, var(--primaryColor) 26%, transparent);
    height: 72px;
    margin: 0 -20px 12px;
    pointer-events: none;
    svg{
      display: block;
      width: 100%;
      height: 100%;
      overflow: visible;
      path{
        animation: footer_wave_flow 9s ease-in-out infinite alternate;
      }
      path:last-child{
        animation-duration: 12s;
        animation-delay: -2s;
      }
    }
  }
  .footer_minimal{
    display: grid;
    gap: 24px;
    grid-template-columns: minmax(0, 1.4fr) minmax(0, 1fr);
    padding-top: 4px;
    &__intro{
      p{
        color: color-mix(in srgb, var(--secondaryTextColor) 88%, var(--ms-white));
        margin: 12px 0 0;
        max-width: 560px;
      }
    }
    .logo{
      padding: 0;
      span{
        font-size: 20px;
      }
    }
    &__meta{
      align-items: flex-end;
      display: flex;
      flex-direction: column;
      gap: 14px;
      justify-content: center;
    }
    &__menu{
      .menunav{
        display: flex;
        flex-wrap: wrap;
        gap: 8px;
        justify-content: flex-end;
        margin: 0;
        padding: 0;
        li{
          list-style: none;
          a{
            border: 1px solid color-mix(in srgb, var(--primaryColor) 17%, transparent);
            border-radius: 999px;
            color: var(--primaryTextColor);
            display: inline-flex;
            font-size: 12px;
            line-height: 1;
            min-height: 36px;
            padding: 0 14px;
            align-items: center;
            &:hover{
              background: var(--primaryColor);
              border-color: var(--primaryColor);
              color: var(--primaryTextBtn);
            }
          }
        }
      }
    }
    &__socials{
      display: flex;
      gap: 8px;
      a{
        align-items: center;
        background: color-mix(in srgb, var(--primaryColor) 12%, transparent);
        border: 1px solid color-mix(in srgb, var(--primaryColor) 20%, transparent);
        border-radius: 50%;
        color: var(--primaryTextColor);
        display: inline-flex;
        height: 40px;
        justify-content: center;
        transition: all .3s;
        width: 40px;
        &:hover{
          background: var(--primaryColor);
          color: var(--primaryTextBtn);
          transform: translateY(-2px);
        }
      }
    }
    &__copyright{
      color: color-mix(in srgb, var(--secondaryTextColor) 92%, var(--ms-white));
      font-size: 13px;
    }
  }
}

@keyframes footer_wave_flow{
  0%{
    transform: translateX(0);
  }
  100%{
    transform: translateX(-18px);
  }
}

@media (max-width: 991px){
  .footer.footer--minimal{
    .footer_minimal{
      grid-template-columns: minmax(0, 1fr);
      text-align: center;
      &__intro{
        .logo{
          justify-content: center;
        }
        p{
          margin-right: auto;
          margin-left: auto;
          max-width: 90%;
        }
      }
      &__meta{
        align-items: center;
      }
      &__menu{
        .menunav{
          justify-content: center;
        }
      }
    }
  }
}

