.float_menu li {
  display: block;
  border-bottom: 1px solid var(--ms-border-color);
  position: relative;
}

.float_menu .menu-item-has-children::after,
.float_menu .menu-item-has-children::before {
  content: "";
  position: absolute;
  width: 10px;
  height: 2px;
  left: 15px;
  top: 23px;
  border-radius: 3px;
  background: #ccc;
}

.float_menu .menu-item-has-children::before {
  transform: scale(1) rotate(90deg);
  transition: all 500ms;
}

.float_menu li.child-minus::before {
  transform: scale(0) rotate(90deg);
  transition: all 500ms;
}

.float_menu li a {
  color: var(--primaryTextColor);
  font-size: 14px;
  padding: 13px;
  display: block;
  transition: all ease 0.5s;
}

.float_menu li a:hover {
  color: #ccc;
}

.float_menu .sub-menu li {
  border-bottom: none;
}

.float_menu .sub-menu li:after,
.float_menu .sub-menu li:before {
  display: none;
}

// Re-enable the expand/collapse arrow for nested items that have their own children (3rd level and deeper)
.float_menu .sub-menu li.menu-item-has-children:after,
.float_menu .sub-menu li.menu-item-has-children:before {
  display: block;
}

.float_menu .sub-menu {
  background: #353640;
}

// Extra indentation per nesting level so deeper children are visually distinguishable
.float_menu .sub-menu .sub-menu li a {
  padding-right: 28px;
}

.float_menu .sub-menu .sub-menu .sub-menu li a {
  padding-right: 43px;
}

.float_menu .sub-menu .sub-menu .sub-menu .sub-menu li a {
  padding-right: 58px;
}

