      .ms-panel__vip-icon {
        background: linear-gradient(145deg, #2dd4bf, #2f80ed);
        border-color: rgba(107, 231, 212, 0.6);
        color: #ecfffb;
      }
    }

    &.is-active {
      border-color: rgba(13, 189, 103, 0.45);
      background: linear-gradient(145deg, rgba(13, 189, 103, 0.22), rgba(13, 189, 103, 0.08));

      .ms-panel__vip-icon {
        border-color: rgba(13, 189, 103, 0.45);
        background: rgba(13, 189, 103, 0.18);
        color: #6ce0a8;
      }

      .ms-panel__vip-value {
        color: #79e7b1;
      }
    }

    &.is-expired {
      border-color: rgba(255, 73, 73, 0.35);
      background: linear-gradient(145deg, rgba(255, 73, 73, 0.18), rgba(255, 73, 73, 0.06));

      .ms-panel__vip-icon {
        border-color: rgba(255, 73, 73, 0.4);
        background: rgba(255, 73, 73, 0.15);
        color: #ff9b9b;
      }

      .ms-panel__vip-value {
        color: #ff8f8f;
      }
    }
  }

  &__dash-grid {
    display: grid;
    grid-template-columns: repeat(2, minmax(0, 1fr));
    gap: 14px;
    margin-top: 12px;
  }

  &__dash-card {
    padding: 14px;
    border-radius: 14px;
    background: linear-gradient(155deg, rgba(255, 255, 255, 0.09), rgba(255, 255, 255, 0.04));
    border: 1px solid rgba(255, 255, 255, 0.1);
    box-shadow: inset 0 1px 0 rgba(255, 255, 255, 0.06), 0 10px 20px rgba(0, 0, 0, 0.14);
    transition: 0.22s ease;

    &:hover {
      transform: translateY(-2px);
      box-shadow: inset 0 1px 0 rgba(255, 255, 255, 0.1), 0 16px 24px rgba(0, 0, 0, 0.18);
    }
  }

  &__dash-head {
    display: flex;
    align-items: center;
    justify-content: space-between;
    gap: 10px;
    margin-bottom: 12px;

    h3 {
      margin: 0;
      color: var(--ms-white);
      font-size: 15px;
      font-weight: 700;
    }

    a {
      color: #aeb9cd;
      font-size: 12px;
      transition: 0.2s ease;

      &:hover {
        color: var(--ms-white);
      }
    }
  }

  &__dash-empty {
    margin: 0;
    color: #aab3c4;
    font-size: 13px;
    line-height: 1.8;
  }

  &__dash-list {
    display: grid;
    gap: 10px;
  }

  &__dash-item {
    display: grid;
    grid-template-columns: 54px minmax(0, 1fr);
    gap: 10px;
    align-items: center;
    padding: 6px;
    border-radius: 12px;
    transition: 0.2s ease;

    &:hover {
      background: rgba(255, 255, 255, 0.06);
    }
  }

  &__dash-thumb {
    width: 54px;
    height: 54px;
    border-radius: 10px;
    overflow: hidden;
    display: block;

    img {
      width: 100%;
      height: 100%;
      object-fit: cover;
    }
  }

  &__dash-content {
    min-width: 0;

    h4 {
      margin: 0 0 3px;
      font-size: 13px;
      line-height: 1.7;

      a {
        color: var(--ms-white);
        display: block;
        overflow: hidden;
        text-overflow: ellipsis;
        white-space: nowrap;
      }
    }

    span {
      font-size: 12px;
      color: #9ba7bc;
      display: block;
      overflow: hidden;
      text-overflow: ellipsis;
      white-space: nowrap;
    }
  }

  &__dash-list--orders {
    gap: 8px;
  }

  &__dash-list--playlists {
    gap: 8px;
  }

  &__dash-playlist {
    display: flex;
    align-items: center;
    justify-content: space-between;
    gap: 10px;
    padding: 10px;
    border-radius: 12px;
    background: rgba(255, 255, 255, 0.04);
    border: 1px solid rgba(255, 255, 255, 0.07);
  }

  &__dash-playlist-meta {
    min-width: 0;

    h4 {
      margin: 0 0 2px;
      font-size: 13px;
      color: var(--ms-white);
      overflow: hidden;
      text-overflow: ellipsis;
      white-space: nowrap;
    }

    span {
      font-size: 11px;
      color: #9ba7bc;
    }
  }

  &__dash-playlist-badge {
    font-size: 11px;
    font-weight: 700;
    border-radius: 999px;
    padding: 4px 8px;
    border: 1px solid rgba(255, 255, 255, 0.15);
    color: #dbe2f0;
    background: rgba(255, 255, 255, 0.08);

    &.is-public {
      border-color: rgba(13, 189, 103, 0.4);
      color: #6ce0a8;
      background: rgba(13, 189, 103, 0.12);
    }
  }

  &__dash-order {
    display: grid;
    grid-template-columns: minmax(0, 1fr) auto auto;
    align-items: center;
    gap: 8px;
    padding: 10px;
    border-radius: 12px;
    background: rgba(255, 255, 255, 0.05);
    border: 1px solid rgba(255, 255, 255, 0.09);
    transition: 0.2s ease;

    &:hover {
      background: rgba(255, 255, 255, 0.08);
    }
  }

  &__dash-order-meta {
    strong {
      display: block;
      color: var(--ms-white);
      font-size: 13px;
      font-weight: 700;
      margin-bottom: 2px;
    }

    span {
      display: block;
      color: #9ba7bc;
      font-size: 11px;
    }
  }

  &__dash-order-state {
    text-align: left;

    span {
      display: block;
      color: #d5dceb;
      font-size: 12px;
      font-weight: 600;
      margin-bottom: 1px;
    }

    small {
      display: block;
      color: #9ba7bc;
      font-size: 11px;
    }
  }

  &__dash-order-link {
    display: inline-flex;
    align-items: center;
    justify-content: center;
    min-height: 32px;
    padding: 0 10px;
    border-radius: 10px;
    background: rgba(255, 255, 255, 0.1);
    border: 1px solid rgba(255, 255, 255, 0.14);
    color: var(--ms-white);
    font-size: 12px;
    font-weight: 600;

    &:hover {
      color: var(--ms-white);
      background: rgba(255, 255, 255, 0.16);
      transform: translateY(-1px);
    }
  }

  &__btn {
    display: inline-flex;
    align-items: center;
    justify-content: center;
    min-width: 140px;
    min-height: 42px;
    padding: 0 16px;
    border-radius: 12px;
    border: 0;
    background: linear-gradient(135deg, var(--primaryColor), var(--secondaryColor));
    color: var(--ms-white);
    font-weight: 700;
    transition: 0.25s ease;

    &:hover {
      color: var(--ms-white);
      transform: translateY(-1px);
      box-shadow: 0 12px 24px rgba(133, 63, 223, 0.28);
    }
  }

  &__btn--neutral {
    background: rgba(255, 255, 255, 0.08);
    border: 1px solid rgba(255, 255, 255, 0.14);
    box-shadow: none;

    &:hover {
      box-shadow: none;
      background: rgba(255, 255, 255, 0.15);
    }
  }

  &__head-btn {
    min-width: 0;
    min-height: 38px;
    border-radius: 10px;
    gap: 6px;
    padding: 0 12px;
    font-size: 13px;
  }

  &__guest {
    padding: 28px;
    text-align: center;
    max-width: 680px;
    margin: 0 auto;

    h1 {
      color: var(--ms-white);
      margin-bottom: 8px;
      font-size: 26px;
    }

    p {
      color: #c8cfda;
      margin-bottom: 18px;
    }
  }

  &__form {
    max-width: 920px;
  }

  &__grid {
    display: grid;
    grid-template-columns: repeat(2, minmax(0, 1fr));
    gap: 14px;
  }

  &__field {
    label {
      display: block;
      margin-bottom: 7px;
      color: #dfe4ed;
      font-size: 13px;
    }

    input,
    textarea {
      width: 100%;
      border: 1px solid rgba(255, 255, 255, 0.12);
      background: rgba(255, 255, 255, 0.06);
      color: var(--ms-white);
      border-radius: 12px;
      padding: 10px 12px;
      outline: 0;
      transition: 0.2s ease;

      &:focus {
        border-color: var(--primaryColor);
        box-shadow: 0 0 0 3px rgba(133, 63, 223, 0.2);
      }
    }

    textarea {
      min-height: 110px;
      resize: vertical;
    }
  }

  &__field--full {
    grid-column: 1 / -1;
  }

  &__form-actions {
    display: flex;
    align-items: center;
    flex-wrap: wrap;
    gap: 12px;
    margin-top: 16px;
  }

  &__notice {
    padding: 9px 12px;
    border-radius: 10px;
    font-size: 13px;
    line-height: 1.6;
    min-height: 42px;
    display: inline-flex;
    align-items: center;
    border: 1px solid transparent;

    &.is-success {
      background: rgba(77, 185, 33, 0.14);
      border-color: rgba(77, 185, 33, 0.35);
      color: #a8e58d;
    }

    &.is-error {
      background: rgba(220, 53, 69, 0.13);
      border-color: rgba(220, 53, 69, 0.34);
      color: #ffb0b8;
    }
  }

  .ms-avatar-editor {
    display: grid;
    grid-template-columns: 96px minmax(0, 1fr);
    gap: 16px;
    align-items: start;
    margin-bottom: 18px;
  }

  .ms-profile-avatar-preview {
    img {
      width: 84px;
      height: 84px;
      border-radius: 50%;
      border: 2px solid var(--primaryColor);
      object-fit: cover;
    }
  }

  .ms-avatar-editor__help {
    margin: 0 0 10px;
    font-size: 13px;
    color: #aab3c4;
  }

  .ms-avatar-upload-card {
    margin-bottom: 10px;
  }

  .ms-avatar-file-input {
    position: absolute;
    opacity: 0;
    pointer-events: none;
    width: 1px;
    height: 1px;
  }

  .ms-avatar-upload-trigger {
    display: flex;
    flex-direction: column;
    gap: 4px;
    border: 1px dashed rgba(255, 255, 255, 0.2);
    border-radius: 12px;
    padding: 12px;
    cursor: pointer;
    transition: 0.2s ease;

    &:hover {
      border-color: var(--primaryColor);
      background: rgba(133, 63, 223, 0.12);
    }

    i {
      color: #c8cfda;
      font-size: 18px;
      line-height: 1;
    }

    strong {
      color: var(--ms-white);
      font-size: 13px;
      font-weight: 700;
    }
  }

  .ms-avatar-upload-hint {
    font-size: 12px;
    color: #94a0b4;
  }

  .ms-avatar-upload-filename {
    font-size: 12px;
    color: #c8cfda;
  }

  .ms-default-avatars-grid {
    display: grid;
    grid-template-columns: repeat(6, minmax(0, 1fr));
    gap: 10px;
  }

  .ms-default-avatar-item {
    display: block;

    input {
      position: absolute;
      opacity: 0;
      pointer-events: none;
    }

    img {
      width: 100%;
      aspect-ratio: 1 / 1;
      object-fit: cover;
      border-radius: 12px;
      border: 2px solid transparent;
      transition: 0.2s ease;
    }

    input:checked + img {
      border-color: var(--primaryColor);
      box-shadow: 0 0 0 3px rgba(133, 63, 223, 0.2);
    }
  }

  .ms-liked-list {
    display: grid;
    gap: 12px;
  }

  .ms-liked-item {
    display: grid;
    grid-template-columns: 68px minmax(0, 1fr) auto;
    align-items: center;
    gap: 12px;
    padding: 10px;
    border-radius: 14px;
    background: rgba(255, 255, 255, 0.05);
    border: 1px solid rgba(255, 255, 255, 0.08);

    &__thumb {
      display: block;
      width: 68px;
      height: 68px;
      border-radius: 10px;
      overflow: hidden;

      img {
        width: 100%;
        height: 100%;
        object-fit: cover;
      }
    }

    &__content {
      min-width: 0;

      h3 {
        margin: 0 0 4px;
        font-size: 14px;
        line-height: 1.8;

        a {
          color: var(--ms-white);
        }
      }

      span {
        color: #a5aec0;
        font-size: 12px;
      }
    }

    &__action {
      .like_btn {
        margin: 0;
      }
    }
  }

  .ms-liked-empty {
    padding: 18px 14px;
    border-radius: 12px;
    background: rgba(255, 255, 255, 0.05);
    border: 1px solid rgba(255, 255, 255, 0.08);
    color: #c8cfda;
  }

  .ms-liked-list {
    grid-template-columns: repeat(6, minmax(0, 1fr));
    gap: 10px;
  }

  .ms-liked-item {
    grid-template-columns: minmax(0, 1fr);
    align-items: stretch;
    gap: 8px;
    padding: 8px;
    border-radius: 12px;

    .ms-liked-item__thumb {
      width: 100%;
      height: auto;
      aspect-ratio: 1 / 1;
      border-radius: 9px;
    }

    .ms-liked-item__content {
      h3 {
        margin-bottom: 2px;
        font-size: 12px;
        line-height: 1.6;

        a {
          display: block;
          overflow: hidden;
          text-overflow: ellipsis;
          white-space: nowrap;
        }
      }

      span {
        display: block;
        font-size: 11px;
        line-height: 1.5;
        overflow: hidden;
        text-overflow: ellipsis;
        white-space: nowrap;
      }
    }

    .ms-liked-item__action {
      .ms-panel__btn {
        width: 100%;
        min-width: 0;
        min-height: 32px;
        padding: 0 8px;
        font-size: 12px;
        font-weight: 600;
        color: var(--ms-white) !important;
        span{
        color: var(--ms-white) !important;
        }
      }
    }
  }

  .ms-follow-item {
    .ms-liked-item__action {
      .ms-panel__btn {
        width: 100%;
      }
    }
  }
}

