/* VIP parity fixes (to match original KelaketFilm visuals) */
.manual-register-form {
  display: flex;
  width: 420px;
  flex-direction: column;
  color: var(--text);
  border-radius: 10px;
  box-shadow: 0 0 200px 0 rgb(0 0 0 / 20%);

  .alert-danger {
    position: relative;
    border-radius: 0.25rem;
    color: #ff2d40;
    background-color: #ff000014;
    padding: 13px;
    font-size: 14px;
    font-weight: 500;
    border: none;
  }
}

.musicsara_checkout {
  .process_checkout_button {
    border: 0;
  }
}

.vpn_message {
  margin-bottom: 10px;
  color: var(--text);

  button {
    background: transparent;
    border: solid 1px var(--primaryColor);
    color: var(--primaryColor);
    padding: 10px 20px;
    margin: 0 20px;
    border-radius: 10px;
    transition: all 0.2s;

    &:hover {
      background: var(--primaryColor);
      color: var(--ms-white);
    }
  }
}

/* VIP Theme Tokens: align VIP module colors with MusicSara palette */
:root {
  --vip-accent: var(--primaryColor);
  --vip-accent-soft: var(--primaryColorLight);
  --vip-success: var(--success);
  --vip-warning: #ffad49;
  --vip-danger: #ff4949;
  --vip-info: #36b9d5;

  --vip-surface: var(--PostItem);
  --vip-surface-2: var(--PostItem2);
  --vip-text: var(--primaryTextColor);
  --vip-muted: var(--secondaryTextColor);
  --vip-border: rgba(148, 163, 184, 0.35);
  --vip-border-strong: rgba(148, 163, 184, 0.5);
}

html.light {
  --vip-surface: var(--ms-white);
  --vip-surface-2: #f5f7f9;
  --vip-text: #3c4354;
  --vip-muted: #667187;
  --vip-border: rgba(60, 67, 84, 0.14);
  --vip-border-strong: rgba(60, 67, 84, 0.22);
}

.musicsara_plans__item,
.musicsara_checkout,
.pay_form,
.pay_instructions-card,
.kcp-history-body {
  color: var(--vip-text);
}

.musicsara_plans__item,
.musicsara_checkout,
.pay_form,
.kcp-history-body {
  background: var(--vip-surface);
}

.musicsara_plans__item .time,
.musicsara_checkout .plan_data,
.musicsara_checkout .discount .head,
.discount_form input,
.gateway_select__wrap .gateway_selct li,
.pay_form .form-control[type="text"],
.custom-file-dropzone,
.preview-wrapper {
  background: var(--vip-surface-2);
}

.musicsara_plans__item .plan_checkout a,
.gateway_select__wrap .gateway_selct li.active,
.pay_form .form-control[type="text"]:focus,
.custom-file-dropzone:hover,
.card-copy-btn:hover,
.vpn_message button,
.discount_form .submit_ajax_discount,
.pay-btn,
.musicsara_checkout .process_checkout_button {
  border-color: var(--vip-accent);
}

.musicsara_plans__item .icon,
.musicsara_plans__item .time span,
.musicsara_plans__item .plan_checkout a,
.vpn_message button {
  color: var(--vip-accent);
}

.discount_form .submit_ajax_discount,
.pay-btn,
.musicsara_checkout .process_checkout_button,
.musicsara_plans__item .plan_checkout a:hover,
.vpn_message button:hover {
  background: var(--vip-accent);
  color: var(--primaryTextBtn);
  border-color: transparent !important;
}

.pay_form,
.pay_instructions-card,
.kcp-history-body,
.card-copy-btn,
.preview-wrapper,
.pay_form .form-control[type="text"],
.custom-file-dropzone {
  border-color: var(--vip-border);
}

.pay_form .form-control[type="text"],
.discount_form input,
.kcp-history-date,
.pay_instructions-text {
  color: var(--vip-muted);
}

.table_badge {
  border-color: var(--vip-warning);
  color: var(--vip-warning);

  &.green {
    border-color: var(--vip-success);
    color: var(--vip-success);
  }

  &.red {
    border-color: var(--vip-danger);
    color: var(--vip-danger);
  }

  &.blue {
    border-color: var(--vip-info);
    color: var(--vip-info);
  }

  &.orange {
    border-color: var(--vip-warning);
    color: var(--vip-warning);
  }
}

.kcp-alert-success {
  border-color: var(--vip-success);
  color: var(--vip-success);
}

.kcp-alert-error {
  border-color: var(--vip-danger);
  color: var(--vip-danger);
}

.vip_header {
  gap: 14px;
