}

/* VIP checkout redesign */
.musicsara_checkout {
  max-width: 980px;
  margin: 12px auto;
  padding: 18px !important;
  border-radius: 18px;
  border: 1px solid var(--vip-border);
  background: linear-gradient(165deg, color-mix(in srgb, var(--vip-surface) 94%, var(--ms-white) 6%), var(--vip-surface));
  box-shadow: 0 16px 34px rgb(0 0 0 / 20%);

  .time {
    margin: 0 auto 16px !important;
    min-height: 42px;
    padding: 8px 16px;
    border-radius: 999px;
    border: 1px solid var(--vip-border);
    background: var(--vip-surface-2);
    color: var(--vip-text);
    font-size: 18px;
    font-weight: 700;
    display: inline-flex;
    align-items: center;
    justify-content: center;
  }

  .plan_data {
    margin: 0 0 16px !important;
    border: 1px solid var(--vip-border);
    border-radius: 14px;
    background: var(--vip-surface-2);

    ul {
      padding: 8px 14px !important;
    }

    li {
      border-bottom: 1px solid var(--vip-border) !important;
      padding: 12px 0 !important;
      color: var(--vip-text);
      font-size: 14px;
      align-items: center;

      &:last-of-type {
        border-bottom: 0 !important;
      }
    }

    .plan_data__title {
      color: var(--vip-muted);
      font-weight: 600;
    }

    #real_price,
    #discounted,
    #now_price {
      font-weight: 800;
      color: var(--vip-text);
    }

    #now_price {
      color: var(--vip-accent);
    }
  }

  .ticket_seprator {
    margin: 18px 0 !important;

    &::before {
      border-color: var(--vip-border) !important;
    }

    .right_dot,
    .left_dot {
      width: 18px;
      height: 18px;
      top: -8px;
      background: var(--vip-surface-2) !important;

      
      // border: 1px solid var(--vip-border);
    }

    .right_dot {
      right: -28px !important;
    }

    .left_dot {
    left: -28px !important;
    }
  }

  .discount {
    margin: 0 0 16px !important;
    border: 1px solid var(--vip-border);
    border-radius: 14px;

    .head {
      padding: 14px !important;
      background: var(--vip-surface-2) !important;
    }

    .title {
      color: var(--vip-text) !important;
      font-size: 14px;
      font-weight: 700;
    }

    .seprator i {
      background: var(--vip-surface) !important;
      color: var(--vip-text);
      border: 1px solid var(--vip-border);
    }

    .body {
      border-top: 1px solid var(--vip-border);
      border-radius: 0 0 14px 14px;
      padding: 14px !important;
    }
  }

  .discount_form {
  
    gap: 10px;
    align-items: center;
    color: var(--vip-muted);

    input {
      margin: 0 !important;
      min-height: 42px;
      border-radius: 10px;
      background: var(--vip-surface) !important;
      border: 1px solid var(--vip-border) !important;
      color: var(--vip-text) !important;
    }

    .submit_ajax_discount {
      margin: 0 !important;
      min-height: 42px;
      border-radius: 10px;
      font-weight: 700;
      padding: 0 14px;
    }
  }

  .gateway_select__wrap {
    margin: 0 0 18px !important;
    padding: 14px;
    border: 1px solid var(--vip-border);
    border-radius: 14px;
    background: var(--vip-surface-2);
    gap: 14px;

    > span {
      color: var(--vip-text);
      font-weight: 700;
      margin: 0 !important;
    }

    .gateway_selct ul {
      gap: 10px !important;
    }

    .gateway_selct li {
      min-width: 120px;
      height: 104px;
      border-radius: 14px;
      background: var(--vip-surface) !important;
      border: 1px solid var(--vip-border) !important;
      color: var(--vip-text);
      font-size: 12px;
      font-weight: 600;
      transition: all .2s ease;

      &.active {
        border-color: var(--vip-accent) !important;
        box-shadow: 0 0 0 2px color-mix(in srgb, var(--vip-accent) 25%, transparent);
      }

      &:hover {
        transform: translateY(-2px);
      }

      img {
        height: 38px !important;
        margin-bottom: 8px !important;
      }
    }
  }

  .process_checkout {
    text-align: center !important;
  }

  .process_checkout_button {
    width: 100%;
    max-width: 260px;
    margin: 0 auto !important;
    min-height: 46px;
    border-radius: 12px !important;
    background: var(--vip-accent) !important;
    border: 1px solid var(--vip-accent) !important;
    color: var(--ms-white) !important;
    font-size: 15px;
    font-weight: 800;
    transition: transform .2s ease, filter .2s ease;

    &:hover {
      filter: brightness(1.06);
      transform: translateY(-1px);
    }
  }
