/* Auth parity with KelaketFilm */
.register {
  margin: 150px 0;
}

.manual-register-form {
  width: 420px;
  color: var(--text);
  border-radius: 10px;
  box-shadow: 0 0 200px 0 rgb(0 0 0 / 20%);

  .logo {
    position: absolute;
    top: -50px;
    left: 50%;
    color: var(--text);
    font-weight: 700;
    transform: translate(-50%, -50%);

    img {
      width: 50px;
      height: 50px;
      max-width: unset;
    }

    span {
      font-size: 16px;
      vertical-align: middle;
    }
  }

  .title {
    text-align: center;
    border-bottom: 1px solid var(--bg2);
    padding: 30px;

    h2 {
      font-size: 18px;
      margin: 0;
    }
  }

  .ajax_form,
  .rcp_login_data {
    padding: 22px;
    margin: 0;
    position: relative;
  }

  .register-input {
    display: inline-block;
    width: 100%;
    height: 57px;
    border: 3px solid var(--bg2);
    border-radius: 10px;
    background: var(--bg);
    color: var(--text);
    font-size: 14px;
    font-weight: 500;
    line-height: 45px;
    padding: 0 5px;
    text-indent: 10px;
    text-align: right;
    margin: 0;
    transition: all .3s;

    &::placeholder {
      color: color-mix(in srgb, var(--text) 55%, transparent);
    }

    &:focus {
      border-color: var(--bg_lighter);
    }
  }

  .input_float_label {
    position: relative;
    margin-bottom: 10px;

    label {
      margin: 0;
      color: color-mix(in srgb, var(--text) 50%, transparent);
      font-size: 15px;
      font-weight: 500;
      background: var(--bg);
      position: relative;
      top: 12px;
      right: 19px;
      padding: 0 7px;
    }
  }

  .kelaket_showpass {
    position: absolute;
    left: 0;
    top: 50%;
    transform: translateY(-50%);
    color: #93939b;
    background: var(--bg);
    border: none;
    font-size: 18px;
    margin-left: 5px;
    cursor: pointer;
  }

  .ajax_from__login,
  .ajax_form__register,
  .submit-reg {
    width: 100%;
    height: 57px;
    border-radius: 10px;
    font-size: 17px;
    font-weight: 800;
    color: var(--ms-white);
    transition: all .3s;
    border: 1px solid var(--primaryColor);
    background: var(--primaryColor);
  }

  .submit_auth_2 {
    background: var(--primaryColor);
    color: var(--primaryTextBtn);
    border: 1px solid var(--primaryColor) !important;
    font-size: 15px;
    font-weight: 700;
    padding: 10px 20px;
    border-radius: 4px;
    width: calc(47% - 14px);
    margin: 10px;
    transition: all .3s;

    &:disabled {
      opacity: .6;
      cursor: wait;
    }
  }

  .lost_pass_link {
    color: #ffffff6e !important;
    margin-top: 20px;
    display: block;
    font-size: 15px !important;
    font-weight: 500;
    transition: all .3s;

    &:hover {
      color: var(--ms-white) !important;
    }
  }

  .custom_register_button {
    color: var(--primaryColor) !important;
    border-radius: 10px;
    border: 1px solid transparent;
    width: 100% !important;
    font-weight: 700;
    text-align: center;
    margin: 0 !important;
    font-size: 17px !important;
    height: 57px;
    display: flex;
    justify-content: center;
    align-items: center;
  }

  .ajax_form__links {
    span {
      font-size: 14px;
    }
  }

  .rcp_error {
    border-radius: .25rem;
    color: #ff2d40;
    background-color: #ff000014;
    padding: 13px;
    font-size: 14px;
    font-weight: 500;
    border: none;
    margin-bottom: 8px;
  }

  .rcp_success {
    border-radius: .25rem;
    color: #0dbd67;
    background-color: #0cbd5014;
    padding: 15px;
    font-size: 15px;
    font-weight: 500;
    border: 1px solid rgb(12 189 102 / 25%);
    margin-bottom: 8px;
  }

  .otp-form {
    .otp-field {
      font-size: 1rem;
      line-height: 2.3rem;
      text-align: center;
      border: 2px solid var(--bg2);
      outline: none;
      background: none;
      width: 100%;
      color: var(--text);
      border-radius: 5px;
      transition: all .3s;

      &:hover,
      &:focus {
        border-color: #3b3b45;
      }
    }
  }

  .otp_cta {
    margin: 20px 0;

    .submit_auth_2 {
      width: 100% !important;
      margin: 0;
    }
  }
