/* WooCommerce in custom panel */
.ms-panel__content-body {
  .woocommerce,
  .woocommerce-MyAccount-content {
    color: var(--text);

    .woocommerce-info,
    .woocommerce-message,
    .woocommerce-error {
      border: 1px solid var(--bg2);
      background: var(--bg_lighter);
      color: var(--text);
      border-radius: 10px;
      padding: 12px 14px;
      margin: 0 0 16px;

      a {
        color: var(--primaryColor);
      }
    }

    form {
      margin: 0;
      padding: 16px;
      background: var(--bg_lighter);
      border: 1px solid var(--bg2);
      border-radius: 12px;
    }

    .form-row,
    .form-row-wide {
      margin-bottom: 14px;
    }

    label {
      display: block;
      margin-bottom: 8px;
      font-weight: 600;
      color: var(--text);
    }

    input[type="text"],
    input[type="email"],
    input[type="tel"],
    input[type="password"],
    input[type="number"],
    textarea,
    select {
      width: 100%;
      height: 46px;
      border-radius: 10px;
      border: 1px solid var(--bg2);
      background: var(--bg);
      color: var(--text);
      padding: 0 12px;
      transition: border-color .2s ease, box-shadow .2s ease;

      &:focus {
        border-color: var(--primaryColor);
        box-shadow: 0 0 0 3px var(--primaryColorLight);
        outline: none;
      }
    }

    textarea {
      min-height: 120px;
      padding: 10px 12px;
    }

    .button,
    button,
    input[type="submit"],
    .woocommerce-button,
    .woocommerce-Button {
      height: 44px;
      border-radius: 10px;
      border: 1px solid var(--primaryColor) !important;
      background: var(--primaryColor) !important;
      color: var(--primaryTextBtn) !important;
      font-weight: 700;
      padding: 0 16px;
      transition: filter .2s ease, opacity .2s ease;

      &:hover {
        filter: brightness(0.95);
      }
    }

    .button.alt,
    .woocommerce-button--previous,
    .woocommerce-Button--previous {
      background: transparent !important;
      color: var(--text) !important;
      border-color: var(--bg2) !important;
    }

    table.shop_table,
    table.woocommerce-orders-table,
    table.woocommerce-table {
      width: 100%;
      border-collapse: separate;
      border-spacing: 0;
      background: var(--bg_lighter);
      border: 1px solid var(--bg2);
      border-radius: 12px;
      overflow: hidden;

      th,
      td {
        border-bottom: 1px solid var(--bg2);
        padding: 12px;
        color: var(--text);
        text-align: right;
      }

      th {
        background: var(--bg);
        font-weight: 700;
      }

      tr:last-child td {
        border-bottom: 0;
      }

      a {
        // color: var(--primaryColor);
      }
    }

    .woocommerce-orders-table__cell-order-actions .button,
    .woocommerce-button.view {
      padding: 0 12px;
      border-radius: 8px;
      font-size: 13px;
      margin: 2px;
    }

    .woocommerce-orders-table__cell-order-number a {
      font-weight: 700;
      font-family: ui-monospace, SFMono-Regular, Menlo, Monaco, Consolas, "Liberation Mono", "Courier New", monospace;
      direction: ltr;
      display: inline-block;
    }

    .woocommerce-orders-table__cell-order-date,
