      align-items: center;
      justify-content: center;
      border-radius: 999px;
      padding: 4px 10px;
      font-size: 12px;
      font-weight: 700;
      border: 1px solid var(--bg2);
      background: var(--bg);
      color: var(--text);

      &.status-completed,
      &.completed {
        background: rgb(22 163 74 / 18%);
        border-color: rgb(22 163 74 / 45%);
        color: #86efac;
      }

      &.status-processing,
      &.processing {
        background: rgb(59 130 246 / 18%);
        border-color: rgb(59 130 246 / 45%);
        color: #93c5fd;
      }

      &.status-on-hold,
      &.on-hold,
      &.status-pending,
