    .woocommerce-address-fields__field-wrapper,
    .woocommerce-Addresses,
    .woocommerce-account-fields {
      display: grid;
      gap: 12px;
    }

    .woocommerce-Address,
    .woocommerce-MyAccount-paymentMethod {
      background: var(--bg_lighter);
      border: 1px solid var(--bg2);
      border-radius: 12px;
      padding: 14px;
      margin-bottom: 12px;
    }

    .woocommerce-Address-title {
      margin-bottom: 10px;
      display: flex;
      align-items: center;
      justify-content: space-between;
      gap: 8px;

      h3 {
        margin: 0;
        font-size: 16px;
      }

      .edit {
        font-size: 12px;
        font-weight: 700;
        background: var(--bg);
        border: 1px solid var(--bg2);
        border-radius: 8px;
        padding: 4px 10px;
        color: var(--primaryColor);
      }
    }

    .woocommerce-downloads-files {
      margin-top: 12px;
    }

    .woocommerce-MyAccount-paymentMethods {
      list-style: none;
      margin: 0;
      padding: 0;
      display: grid;
      gap: 12px;
    }

    .woocommerce-MyAccount-paymentMethod {
      display: grid;
      gap: 10px;

      .payment-method-actions {
        display: flex;
        gap: 8px;
        flex-wrap: wrap;

        .button {
          height: 34px;
          line-height: 32px;
          border-radius: 8px;
          font-size: 12px;
          padding: 0 10px;
        }
      }
    }

    .woocommerce-order {
      display: grid;
      gap: 14px;
    }

    .woocommerce-order-overview {
      list-style: none;
      margin: 0;
      padding: 0;
      display: grid;
      grid-template-columns: repeat(4, minmax(0, 1fr));
      gap: 10px;

      li {
        border: 1px solid var(--bg2);
        background: var(--bg_lighter);
        border-radius: 10px;
        padding: 10px;
        font-size: 12px;
        color: #aeb7d2;

        strong {
          display: block;
          margin-top: 4px;
          color: var(--text);
          font-size: 14px;
        }
      }
    }

    .woocommerce-order-details,
    .woocommerce-customer-details,
    .woocommerce-column--billing-address,
    .woocommerce-column--shipping-address {
      border: 1px solid var(--bg2);
      background: var(--bg_lighter);
      border-radius: 12px;
      padding: 14px;
    }

    /* Dedicated polish for my-account view-order endpoint */
    .woocommerce-order-details,
    .woocommerce-order-downloads,
    .woocommerce-customer-details {
      .woocommerce-order-details__title,
      .woocommerce-order-downloads__title,
      .woocommerce-column__title {
        font-size: 17px;
        margin-bottom: 12px;
        padding-bottom: 10px;
        border-bottom: 1px dashed var(--bg2);
      }
    }

    .woocommerce-table--order-details {
      th,
      td {
        vertical-align: middle;
      }

      .product-name a {
        color: var(--text);
        font-weight: 700;
      }

      .product-total,
      .woocommerce-Price-amount {
        font-weight: 700;
      }

      tfoot tr:last-child {
        th,
        td {
          color: var(--primaryColor);
          font-size: 15px;
        }
      }
    }

    .woocommerce-OrderUpdates {
      list-style: none;
      margin: 0;
      padding: 0;
      display: grid;
      gap: 10px;

      li {
        border: 1px solid var(--bg2);
        background: var(--bg_lighter);
        border-radius: 10px;
        padding: 12px;
      }

      p {
        margin: 0;
        color: var(--text);
        font-size: 13px;
      }

      .meta {
        margin-top: 6px;
        color: #aeb7d2;
        font-size: 12px;
      }
    }

    .order-again {
      margin-top: 4px;

      .button {
        min-width: 170px;
      }
    }
  }
}

