/* Unified Auth Design System */
body.page-auth-email,
body.page-auth-mobile {
  background: var(--bg);
  color: var(--text);
  min-height: 100vh;
  position: relative;
  overflow-x: hidden;

  &::before {
    content: "";
    position: fixed;
    top: 0;
    left: 50%;
    transform: translateX(-50%);
    width: min(1280px, 100vw);
    height: 360px;
    pointer-events: none;
    z-index: 0;
    background: radial-gradient(
      ellipse at top,
      color-mix(in srgb, var(--primaryColor) 34%, transparent) 0%,
      color-mix(in srgb, var(--primaryColor) 22%, transparent) 38%,
      transparent 74%
    );
  }

  .ms-auth-shell {
    margin: 126px 0 88px;
    display: flex;
    justify-content: center;
    position: relative;
    z-index: 2;
  }

  .manual-register-form {
    width: min(92vw, 448px) !important;
    max-width: 448px;
    border: 1px solid color-mix(in srgb, var(--bg2) 92%, transparent);
    border-radius: 18px;
    background: color-mix(in srgb, var(--bg) 94%, #111420);
    box-shadow:
      0 28px 80px rgba(4, 9, 20, 0.45),
      inset 0 1px 0 rgba(255, 255, 255, 0.04);
    overflow: hidden;

    .logo {
      top: -44px;
    }

    .title {
      border-bottom: 1px solid color-mix(in srgb, var(--bg2) 88%, transparent);
      padding: 23px 22px 16px;

      h2 {
        margin: 0;
        font-size: 21px;
        font-weight: 600;
      }
    }

    .ajax_form,
    .rcp_login_data {
      margin: 0;
      padding: 20px 22px;
    }

    .input_float_label {
      margin: 0 0 16px;
      position: relative;
      display: grid;
      gap: 8px;

      label {
        margin: 0;
        position: static;
        padding: 0;
        border: 0;
        font-size: 12px;
        font-weight: 500;
        line-height: 1.2;
        letter-spacing: .02em;
        color: color-mix(in srgb, var(--text) 60%, transparent);
        transition: color .2s ease, transform .2s ease;
      }

      &:focus-within label {
        color: var(--primaryColor);
        transform: translateY(-1px);
      }
