      padding: 0 14px;
      line-height: 56px;
      font-size: 15px;
      font-weight: 500;

      &::placeholder {
        color: color-mix(in srgb, var(--text) 45%, transparent);
      }

      &:focus {
        border-color: var(--primaryColor);
        box-shadow:
          0 0 0 3px color-mix(in srgb, var(--primaryColor) 14%, transparent),
          0 8px 24px color-mix(in srgb, var(--primaryColor) 12%, transparent);
        outline: none;
      }
    }

    .ajax_form__register,
    .ajax_from__login,
    .submit-reg,
    .submit_auth_2 {
      width: 100%;
      height: 56px;
      border-radius: 15px;
      border: 1px solid var(--primaryColor) !important;
      background: var(--primaryColor) !important;
      color: var(--primaryTextBtn) !important;
      font-size: 16px;
      font-weight: 600;
      transition: transform .2s ease, filter .2s ease, box-shadow .2s ease;
      box-shadow: 0 10px 28px color-mix(in srgb, var(--primaryColor) 24%, transparent);

      &:hover {
        filter: brightness(.97);
        transform: translateY(-1px);
      }
