    .custom_register_button {
      border: 1px solid var(--bg2);
      border-radius: 14px;
      background: color-mix(in srgb, var(--bg_darker) 80%, var(--bg));
      color: var(--primaryColor) !important;
      height: 56px;
      font-size: 16px !important;
      font-weight: 600;
