}

.header .leftSide .light_switch button::before {
  content: '';
  position: absolute;
  inset: 0;
  background: linear-gradient(180deg, #101827 0%, #0b1220 100%);
  transition: opacity .45s ease;
  opacity: 1;
}

.header .leftSide .light_switch button::after {
  content: '';
  position: absolute;
  top: 9px;
  left: 9px;
  width: 12px;
  height: 12px;
  border-radius: 50%;
  background: #dce7ff;
  box-shadow: 0 0 0 3px rgba(220, 231, 255, 0.18);
  transition: transform .45s cubic-bezier(.4, 0, .2, 1), background .45s ease, box-shadow .45s ease;
  transform: translateX(0);
