@keyframes msSunrise {
  0% { transform: rotate(-30deg) scale(.92); opacity: .7; }
  100% { transform: rotate(0deg) scale(1); opacity: 1; }
}

@keyframes msMoonrise {
  0% { transform: rotate(30deg) scale(.92); opacity: .7; }
  100% { transform: rotate(0deg) scale(1); opacity: 1; }
}

