// Playlist collage/cover-cell markup only ever appears inside a playlist card
// (see musicsara_get_playlist_items_data() usage), never inside a regular post's
// .music_card, so these are safe to apply globally instead of scoping them under
// .ms-public-playlists — this is what lets playlist cards mixed into the site
// search results grid (search.php / archive/modern.php) render correctly too.
.music_card .ms-playlist-collage {
  display: grid;
  grid-template-columns: repeat(2, minmax(0, 1fr));
  gap: 0;
}

.music_card .ms-playlist-collage img {
  border-radius: unset;
}

.music_card .ms-playlist-cover-cell {
  min-height: auto;
  aspect-ratio: 1 / 1;
  border-radius: 0;
  overflow: hidden;
}

.music_card .ms-playlist-cover-cell:nth-child(1) {
  border-top-right-radius: 10px;
}

.music_card .ms-playlist-cover-cell:nth-child(2) {
  border-top-left-radius: 10px;
}

.music_card .ms-playlist-cover-cell:nth-child(3) {
  border-bottom-right-radius: 10px;
}

.music_card .ms-playlist-cover-cell:nth-child(4) {
  border-bottom-left-radius: 10px;
}

.music_card .ms-playlist-collage--single {
  grid-template-columns: 1fr;
}

.music_card .ms-playlist-collage--single .ms-playlist-cover-cell {
  border-radius: 10px;
}

// .music_card .swiper_image img and .single_info__cover img set height:auto
// with higher specificity than the base .ms-playlist-cover-cell img rule, so
// without these overrides a non-square cover image (especially the custom
// single artwork) doesn't get cropped to fill its square cell and leaves gaps.
.music_card .swiper_image .ms-playlist-cover-cell img,
.single_info__cover .ms-playlist-cover-cell img {
  width: 100%;
  height: 100%;
  object-fit: cover;
}

// The single custom-cover box has no other width constraint (unlike the 4-tile
// collage, which is incidentally bounded by the small intrinsic size of track
// thumbnails), so without a cap it grows to the full pixel size of the
// uploaded artwork.
.ms-playlist-single-info .single_info__cover .ms-playlist-collage {
  width: 100%;
  max-width: 210px;
}

.phone_wraper, .resend-wrap{
  color: var(--primaryTextColor);
}


/* =====================================================================
   Sticky player — redesigned bar, waveform seek & mini bubble
   ================================================================== */

#player{
  --ms-wave-pos: 0%;
  --ms-wave-height: 30px;
  --ms-player-accent: var(--primaryColor);
  --ms-player-muted: #9aa6ba;
  --ms-player-hover: rgba(255, 255, 255, .09);
  --ms-wave-idle: rgba(255, 255, 255, .24);
  --plyr-color-main: var(--primaryColor);
  overflow: visible;

  // The audio element sits inside a bootstrap container; let it fill the pill.
  > .container,
  > .container-fluid{
    max-width: 100%;
    padding-left: 14px;
    padding-right: 14px;
  }

  .plyr{
    min-width: 0;
  }
}

/* --- layout ------------------------------------------------------- */
// The meta shrinks to its content (capped) and the tools to their icons, so the
// transport + waveform column absorbs every remaining pixel.
#player .ms-player-bar{
  display: grid;
  grid-template-columns: auto minmax(0, 1fr) auto;
  align-items: center;
  gap: 14px;
  padding: 9px 0 !important;
  background: transparent;
}

#player .ms-player-bar__meta{
  display: flex;
  align-items: center;
  gap: 10px;
  min-width: 0;
  max-width: 260px;
}

#player .ms-player-bar__main{
  display: grid;
  gap: 4px;
  min-width: 0;
}

#player .ms-player-bar__tools{
  display: flex;
  align-items: center;
  justify-content: flex-start;
  gap: 2px;
}

/* --- artwork ------------------------------------------------------ */
#player .ms-player-art{
  position: relative;
  flex: 0 0 auto;
  width: 46px;
  height: 46px;
  border-radius: 13px;
  overflow: hidden;
  display: grid;
  place-items: center;
  background: linear-gradient(140deg, rgba(255, 255, 255, .16), rgba(255, 255, 255, .04));
  box-shadow: 0 6px 16px -8px rgba(0, 0, 0, .8);

  &__img{
    display: none;
    width: 100%;
    height: 100%;
    object-fit: cover;
  }

  &__placeholder{
    font-size: 18px;
    line-height: 0;
    color: var(--ms-player-muted);
  }

  &.has-art{
    .ms-player-art__img{ display: block; }
    .ms-player-art__placeholder{ display: none; }
  }

  &__eq{
    position: absolute;
    inset: 0;
    display: none;
    align-items: flex-end;
    justify-content: center;
    gap: 2px;
    padding-bottom: 8px;
    background: rgba(0, 0, 0, .38);

    i{
      display: block;
      width: 3px;
      height: 7px;
      border-radius: 2px;
      background: var(--ms-white);
      transform-origin: bottom;
    }
  }
}

#player.ms-player--no-art .ms-player-art{
  display: none;
}

#player.is-playing .ms-player-art__eq{
  display: flex;
}

#player.is-playing:not(.ms-player--wave-static) .ms-player-art__eq i{
  animation: msPlayerEq .9s ease-in-out infinite;

  &:nth-child(2){ animation-delay: -.18s; }
  &:nth-child(3){ animation-delay: -.36s; }
  &:nth-child(4){ animation-delay: -.54s; }
}

@keyframes msPlayerEq{
  0%, 100%{ transform: scaleY(.5); }
  50%     { transform: scaleY(2.1); }
}

/* --- track meta --------------------------------------------------- */
#player .ms-player-meta{
  display: grid;
  gap: 2px;
  min-width: 0;

  &__sub{
    font-size: 11px;
    line-height: 1.5;
    color: var(--ms-player-muted);
    white-space: nowrap;
    overflow: hidden;
    text-overflow: ellipsis;

    &:empty{ display: none; }
  }
}

#player .song_name{
  display: block;
  font-size: 13px;
  font-weight: 700;
  line-height: 1.5;
  color: var(--primaryTextColor);
  white-space: nowrap;
  overflow: hidden;
  text-overflow: ellipsis;
}

/* --- transport buttons -------------------------------------------- */
#player .ms-player-buttons{
  display: flex;
  align-items: center;
  justify-content: center;
  gap: 4px;
}

#player .ms-player-buttons .plyr__control{
  color: var(--primaryTextColor);
  background: transparent;
  border-radius: 50%;
  padding: 7px;
  margin: 0;
  transition: background .2s ease, transform .2s ease, color .2s ease;

  &:hover{
    background: var(--ms-player-hover) !important;
    color: var(--primaryTextColor) !important;
  }

  &:active{ transform: scale(.94); }
}

#player .ms-player-buttons .play_button{
  width: 42px;
  height: 42px;
  padding: 0 !important;
  display: grid;
  place-items: center;
  background: var(--primaryColor) !important;
  color: var(--ms-white) !important;
  box-shadow: 0 8px 20px -8px var(--primaryColor);

  svg{
    width: 15px;
    height: 15px;
  }

  &:hover{
    background: var(--primaryColor) !important;
    color: var(--ms-white) !important;
    transform: scale(1.06);
  }
}

/* --- seek row ----------------------------------------------------- */
#player .ms-player-seek{
  display: flex;
  align-items: center;
  gap: 10px;
  direction: ltr;

  .plyr__time{
    flex: 0 0 auto;
    min-width: 38px;
    font-size: 11px;
    line-height: 1.4;
    color: var(--ms-player-muted);
    font-variant-numeric: tabular-nums;
    text-align: center;
    margin: 0 !important;
    padding: 0 !important;
  }

  .plyr__progress__container{
    flex: 1 1 auto;
    min-width: 0;
    padding: 0 !important;
  }
}

#player .plyr__progress{
  position: relative;
  left: 0 !important;
  margin: 0 !important;
  height: var(--ms-wave-height);
  display: flex;
  align-items: center;

  .plyr__progress__buffer{
    display: none;
  }

  .plyr__tooltip{
    z-index: 8;
  }
}

#player .plyr__progress input[type=range]{
  position: absolute;
  inset: 0;
  width: 100% !important;
  height: 100% !important;
  margin: 0 !important;
  padding: 0;
  opacity: 0;
  z-index: 5;
  cursor: pointer;
}

/* Plain line style keeps the native plyr track, just tidied up. */
#player[data-wave-style="line"]{
  --ms-wave-height: 20px;

  .plyr__progress input[type=range]{
    opacity: 1;
    --plyr-range-track-height: 5px;
    --plyr-range-thumb-height: 12px;
  }
}

/* --- waveform ----------------------------------------------------- */
#player .ms-wave{
  position: absolute;
  inset: 0;
  z-index: 2;
  pointer-events: none;
  overflow: hidden;
  border-radius: 4px;

  &__layer{
    position: absolute;
    inset: 0;
    display: flex;
    align-items: flex-end;
    gap: var(--ms-wave-gap, 2px);
    height: 100%;

    &--bg{ color: var(--ms-wave-idle); }

    &--fill{
      color: var(--ms-player-accent);
      clip-path: inset(0 calc(100% - var(--ms-wave-pos)) 0 0);
    }
  }

  // No min-width: the bar count is already capped to what the width can
  // resolve, so letting these go sub-pixel is what makes dense waves fine.
  &__bar{
    flex: 1 1 0;
    min-width: 0;
    height: var(--h, 50%);
    border-radius: 2px;
    background: currentColor;
    transform-origin: bottom center;
  }

  &__svg{
    width: 100%;
    height: 100%;
    display: block;

    path{ fill: currentColor; }
  }

  &__head{
    position: absolute;
    top: 50%;
    left: var(--ms-wave-pos);
    width: 2px;
    height: 100%;
    border-radius: 2px;
    background: var(--ms-white);
    box-shadow: 0 0 10px rgba(255, 255, 255, .55);
    transform: translate(-50%, -50%);
    opacity: 0;
    transition: opacity .2s ease;
  }
}

#player[data-wave-style="mirror"] .ms-wave__layer{
  align-items: center;
}

#player[data-wave-style="mirror"] .ms-wave__bar{
  transform-origin: center;
}

#player.is-playing .ms-wave__head,
#player .plyr__progress:hover .ms-wave__head{
  opacity: .85;
}

// --ms-wave-step is normalised against the bar count in JS, so neighbouring
// bars stay near-in-phase and the row undulates as one travelling wave rather
// than flickering — which is what a fixed step did once bars got thin.
#player.is-playing:not(.ms-player--wave-static) .ms-wave__bar{
  animation: msWaveBar 1.7s ease-in-out infinite;
  animation-delay: calc(var(--i, 0) * var(--ms-wave-step, -30ms));
}

#player.is-playing:not(.ms-player--wave-static)[data-wave-style="wave"] .ms-wave__svg{
  animation: msWaveBreathe 2.8s ease-in-out infinite;
  transform-origin: center;
}

@keyframes msWaveBar{
  0%, 100%{ transform: scaleY(.87); }
  50%     { transform: scaleY(1.1); }
}

@keyframes msWaveBreathe{
  0%, 100%{ transform: scaleY(.88); }
  50%     { transform: scaleY(1.05); }
}

@media (prefers-reduced-motion: reduce){
  #player .ms-wave__bar,
  #player .ms-wave__svg,
  #player .ms-player-art__eq i{
    animation: none !important;
  }
}

/* --- tools cluster ------------------------------------------------ */
#player .ms-player-bar__tools .plyr__control{
  width: 34px;
  height: 34px;
  min-width: 34px;
  min-height: 34px;
  padding: 0;
  margin: 0;
  display: grid;
  place-items: center;
  border-radius: 11px;
  color: var(--ms-player-muted);
  background: transparent;
  transition: background .2s ease, color .2s ease;

  i{
    font-size: 15px;
    line-height: 1;
  }

  &:hover{
    background: var(--ms-player-hover) !important;
    color: var(--primaryTextColor) !important;
  }
}

#player .custom_queue_toggle{
  color: var(--primaryColor) !important;
}

#player.ms-queue-open .custom_queue_toggle{
  background: var(--primaryColorLight) !important;
}

#player .ms-player-minimize i{
  font-size: 17px;
}

#player .ms-player-stop:hover{
  color: var(--primaryColor) !important;
}

#player .plyr__volume{
  min-width: auto;
  max-width: none;
  width: auto;
  margin: 0 2px;

  input[type=range]{
    width: 66px;
    max-width: 66px;
    margin-left: 2px;
  }

  .plyr__control{
    color: var(--ms-player-muted);
    padding: 6px;
  }
}

/* --- mini bubble -------------------------------------------------- */
#open_player{
  --ms-wave-pos: 0%;
  position: fixed;
  z-index: 999;
  bottom: 16px;
  right: 18px;
  display: none;
  align-items: center;
  gap: 9px;
  max-width: min(320px, calc(100vw - 32px));
  padding: 6px;
  border-radius: 999px;
  background: rgba(24, 25, 32, .74);
  backdrop-filter: blur(28px) saturate(180%);
  border: 1px solid rgba(255, 255, 255, .12);
  box-shadow: 0 18px 42px -18px rgba(0, 0, 0, .85);
  color: var(--primaryTextColor);
  cursor: pointer;
  transition: transform .25s ease, box-shadow .25s ease;

  &:hover{
    transform: translateY(-2px);
    box-shadow: 0 22px 46px -18px rgba(0, 0, 0, .9);
  }

  &.is-visible{
    animation: msMiniIn .32s cubic-bezier(.2, .8, .3, 1) both;
  }

  .ms-mini__art{
    position: relative;
    flex: 0 0 auto;
    width: 42px;
    height: 42px;
    padding: 2px;
    border-radius: 50%;
    display: grid;
    place-items: center;
    background: conic-gradient(var(--primaryColor) var(--ms-wave-pos), rgba(255, 255, 255, .16) 0);

    &::after{
      content: '';
      position: absolute;
      inset: 2px;
      border-radius: 50%;
      background: rgba(20, 21, 27, .92);
    }
  }

  .ms-mini__img{
    position: relative;
    z-index: 2;
    display: none;
    width: 100%;
    height: 100%;
    border-radius: 50%;
    object-fit: cover;
  }

  .ms-mini__placeholder{
    position: relative;
    z-index: 2;
    font-size: 15px;
    line-height: 0;
    color: var(--ms-player-muted, #9aa6ba);
  }

  &.has-art{
    .ms-mini__img{ display: block; }
    .ms-mini__placeholder{ display: none; }
  }

  &.is-playing .ms-mini__img{
    animation: msMiniSpin 10s linear infinite;
  }

  .ms-mini__body{
    display: grid;
    gap: 1px;
    min-width: 0;
    max-width: 148px;
    text-align: start;
  }

  .ms-mini__title{
    font-size: 12px;
    font-weight: 700;
    line-height: 1.5;
    white-space: nowrap;
    overflow: hidden;
    text-overflow: ellipsis;
  }

  .ms-mini__sub{
    font-size: 10px;
    line-height: 1.5;
    color: var(--secondaryTextColor);
    white-space: nowrap;
    overflow: hidden;
    text-overflow: ellipsis;
  }

  .ms-mini__btn{
    flex: 0 0 auto;
    width: 30px;
    height: 30px;
    padding: 0;
    border: 0;
    border-radius: 50%;
    display: grid;
    place-items: center;
    line-height: 0;
    font-size: 15px;
    background: transparent;
    color: var(--primaryTextColor);
    transition: background .2s ease, color .2s ease, transform .2s ease;

    &:hover{ background: rgba(255, 255, 255, .12); }
    &:active{ transform: scale(.92); }
  }

  .ms-mini__play{
    background: var(--primaryColor);
    color: var(--ms-white);
    font-size: 17px;
    box-shadow: 0 6px 16px -6px var(--primaryColor);

    &:hover{ background: var(--primaryColor); }
  }

  .ms-mini__close{
    font-size: 16px;
    color: var(--secondaryTextColor);

    &:hover{ color: var(--primaryColor); }
  }
}

@keyframes msMiniIn{
  from{ opacity: 0; transform: translateY(14px) scale(.94); }
  to  { opacity: 1; transform: translateY(0) scale(1); }
}

@keyframes msMiniSpin{
  to{ transform: rotate(360deg); }
}

@media (prefers-reduced-motion: reduce){
  #open_player.is-playing .ms-mini__img,
  #open_player.is-visible{
    animation: none !important;
  }
}

/* --- responsive --------------------------------------------------- */
@media screen and (max-width: 991px){
  #player .ms-player-bar{
    grid-template-columns: minmax(0, 1fr) auto;
    grid-template-areas:
      "meta tools"
      "main main";
    row-gap: 4px;
  }

  #player .ms-player-bar__meta{ grid-area: meta; }
  #player .ms-player-bar__main{ grid-area: main; }
  #player .ms-player-bar__tools{ grid-area: tools; }
}

@media screen and (max-width: 767px){
  #player{
    --ms-wave-height: 24px;

    > .container,
    > .container-fluid{
      padding-left: 10px;
      padding-right: 10px;
    }

    .ms-player-art{
      width: 40px;
      height: 40px;
      border-radius: 11px;
    }

    .play_button{
      width: 38px;
      height: 38px;
    }

    .ms-player-bar__tools .plyr__control{
      width: 32px;
      height: 32px;
      min-width: 32px;
      min-height: 32px;
    }
  }

  #open_player{
    right: 12px;
    bottom: 12px;
  }
}

@media screen and (max-width: 500px){
  #player .ms-player-seek .plyr__time{
    min-width: 34px;
    font-size: 10px;
  }

  #open_player .ms-mini__body{
    display: none;
  }
}

/* --- light theme -------------------------------------------------- */
