/* =========================================================================
   Single demo: Aurora
   A glass / gradient take on the single page. Colors come only from the
   theme CSS variables so it follows the palette picked in theme options.
   ========================================================================= */

.aurora_demo{
  --aurora-radius: 22px;
  --aurora-panel-bg: var(--ms-card-bg);
  --aurora-line: color-mix(in srgb, var(--primaryTextColor) 12%, transparent);
  --aurora-line-soft: color-mix(in srgb, var(--primaryTextColor) 7%, transparent);
  --aurora-shadow: 0 22px 45px -28px var(--ms-shadow-color);
  --aurora-gradient: linear-gradient(135deg, var(--primaryColor), var(--secondaryColor));

  /* ---------- hero ---------- */
  .aurora_hero{
    position: relative;
    isolation: isolate;
    overflow: hidden;
    border-radius: 26px;
    border: 1px solid var(--aurora-line);
    background: var(--aurora-panel-bg);
    box-shadow: var(--aurora-shadow);
    padding: 32px;
    margin: 8px 0 26px;

    &__backdrop{
      position: absolute;
      inset: -25%;
      z-index: -2;
      background-size: cover;
      background-position: center;
      filter: blur(70px) saturate(170%);
      opacity: .5;
      transform: scale(1.15);
    }

    &::after{
      content: "";
      position: absolute;
      inset: 0;
      z-index: -1;
      background: linear-gradient(
        160deg,
        color-mix(in srgb, var(--ms-card-bg) 62%, transparent),
        color-mix(in srgb, var(--ms-card-bg) 94%, transparent)
      );
    }

    &__glow{
      position: absolute;
      z-index: -1;
      width: 320px;
      height: 320px;
      border-radius: 50%;
      filter: blur(90px);
      pointer-events: none;
      opacity: .55;

      &--one{
        inset-block-start: -140px;
        inset-inline-end: -80px;
        background: var(--primaryColor);
      }
      &--two{
        inset-block-end: -170px;
        inset-inline-start: -60px;
        background: var(--secondaryColor);
      }
    }

    &__inner{
      position: relative;
      display: flex;
      align-items: flex-end;
      gap: 28px;
    }

    &__cover{
      flex: 0 0 208px;
      width: 208px;
      margin: 0 !important;

      img{
        width: 100%;
        height: auto;
        display: block;
        border-radius: 18px;
        box-shadow: 0 26px 50px -22px rgba(0, 0, 0, .75);
      }

      .type_overlay{
        position: absolute;
        inset-block-start: 10px;
        inset-inline-end: 10px;

        a{
          display: inline-block;
          font-size: 11px;
          font-weight: 600;
          padding: 4px 10px;
          border-radius: 30px;
          color: var(--ms-white);
          background: color-mix(in srgb, var(--ms-black) 45%, transparent);
          backdrop-filter: blur(6px);
          border: 1px solid color-mix(in srgb, var(--ms-white) 22%, transparent);
        }
      }
    }

    &__body{
      flex: 1 1 320px;
      min-width: 0;
    }

    &__genres{
      display: flex;
      flex-wrap: wrap;
      gap: 6px;
      margin-bottom: 12px;

      a{
        font-size: 11px;
        font-weight: 600;
        padding: 4px 12px;
        border-radius: 30px;
        margin: 0;
        color: var(--primaryColor);
        background: color-mix(in srgb, var(--primaryColor) 12%, transparent);
        border: 1px solid color-mix(in srgb, var(--primaryColor) 35%, transparent);
        transition: .2s ease;

        &:hover{
          background: var(--primaryColor);
          color: var(--primaryTextBtn);
        }
      }
    }

    h1{
      font-size: clamp(22px, 2.6vw, 34px);
      font-weight: 800;
      line-height: 1.4;
      margin: 0 0 12px;
      color: var(--primaryTextColor);
    }

    &__artists{
      display: flex;
      flex-wrap: wrap;
      gap: 8px;
      margin-bottom: 16px;

      a{
        display: inline-flex;
        align-items: center;
        gap: 6px;
        font-size: 12px;
        font-weight: 600;
        padding: 6px 14px;
        border-radius: 30px;
        color: var(--primaryTextColor);
        background: color-mix(in srgb, var(--primaryTextColor) 8%, transparent);
        border: 1px solid var(--aurora-line);
        transition: .2s ease;

        &::before{
          content: "";
          width: 6px;
          height: 6px;
          border-radius: 50%;
          background: var(--aurora-gradient);
        }

        &:hover{
          border-color: color-mix(in srgb, var(--primaryColor) 55%, transparent);
          color: var(--primaryColor);
        }
      }
    }

    &__stats{
      list-style: none;
      display: flex;
      flex-wrap: wrap;
      gap: 18px;
      padding: 0;
      margin: 0 0 20px;

      li{
        display: inline-flex;
        align-items: center;
        gap: 6px;
        font-size: 12px;
        color: var(--secondaryTextColor);
      }

      i{
        font-size: 14px;
        color: var(--primaryColor);
      }
    }

    &__actions{
      display: flex;
      align-items: center;
      flex-wrap: wrap;
      gap: 10px;
      position: relative;
    }
  }

  /* ---------- hero buttons ---------- */
  .aurora_play{
    display: inline-flex;
    align-items: center;
    gap: 8px;
    border: none;
    outline: none;
    padding: 0 22px 0 18px;
    height: 46px;
    border-radius: 30px;
    font-size: 14px;
    font-weight: 700;
    color: var(--primaryTextBtn);
    background: var(--aurora-gradient);
    transition: transform .2s ease, box-shadow .2s ease, filter .2s ease;

    i{
      font-size: 22px;
      line-height: 0;
    }

    &:hover{
      transform: translateY(-2px);
      filter: saturate(115%);
      box-shadow: 0 18px 34px -14px color-mix(in srgb, var(--primaryColor) 90%, var(--ms-black));
    }
  }

  .aurora_ghost_btn{
    display: inline-flex;
    align-items: center;
    gap: 8px;
    height: 46px;
    padding: 0 18px;
    border-radius: 30px;
    font-size: 13px;
    font-weight: 600;
    outline: none;
    color: var(--primaryTextColor);
    background: color-mix(in srgb, var(--primaryTextColor) 7%, transparent);
    border: 1px solid var(--aurora-line);
    transition: .2s ease;

    i{ font-size: 16px; line-height: 0; }

    &:hover{
      color: var(--primaryColor);
      border-color: color-mix(in srgb, var(--primaryColor) 55%, transparent);
      background: color-mix(in srgb, var(--primaryColor) 10%, transparent);
    }
  }

  .aurora_hero__actions{
    .like_btn,
    .share_toggle,
    .ms-add-to-playlist{
      width: 46px;
      height: 46px;
      min-height: 46px;
      padding: 0;
      margin: 0;
      display: inline-flex;
      align-items: center;
      justify-content: center;
      line-height: 0;
      border-radius: 50%;
      outline: none;
      color: var(--primaryTextColor);
      background: color-mix(in srgb, var(--primaryTextColor) 7%, transparent);
      border: 1px solid var(--aurora-line);
      transition: .2s ease;

      span:not(.like-button){ display: none; }

      i,
      .like-button{
        font-size: 16px;
        line-height: 0;
        color: inherit;
      }

      &:hover{
        color: var(--primaryColor);
        border-color: color-mix(in srgb, var(--primaryColor) 55%, transparent);
        background: color-mix(in srgb, var(--primaryColor) 10%, transparent);
      }
    }

    .like_btn .like-button.bi-heart-fill{
      color: var(--primaryColor);
    }

    .share_dialog{
      display: none;
      position: absolute;
      inset-block-start: 56px;
      inset-inline-end: 0;
      z-index: 5;
      gap: 8px;
      padding: 10px;
      border-radius: 14px;
      background: var(--ms-card-bg);
      border: 1px solid var(--aurora-line);
      box-shadow: var(--aurora-shadow);

      &.active{ display: flex !important; }

      a{
        width: 34px;
        height: 34px;
        display: flex;
        align-items: center;
        justify-content: center;
        border-radius: 50%;
        font-size: 14px;
        color: var(--secondaryTextColor);
        border: 1px solid var(--aurora-line);
        transition: .2s ease;
      }

      .whatsapp:hover{ background: #25d366; border-color: #25d366; color: var(--ms-white); }
      .telegram:hover{ background: #0a66c2; border-color: #0a66c2; color: var(--ms-white); }
      .twitter:hover{  background: #1da1f2; border-color: #1da1f2; color: var(--ms-white); }
    }
  }

  /* ---------- panels ---------- */
  .aurora_panel{
    position: relative;
    background: var(--aurora-panel-bg);
    border: 1px solid var(--aurora-line-soft);
    border-radius: var(--aurora-radius);
    padding: 20px;
    margin-bottom: 20px;
    box-shadow: var(--aurora-shadow);

    &--flush{
      padding: 10px;
      overflow: hidden;
    }

    &__header{
      display: flex;
      align-items: center;
      justify-content: space-between;
      gap: 10px;
      margin-bottom: 16px;

      h3{
        display: flex;
        align-items: center;
        gap: 10px;
        font-size: 15px;
        font-weight: 700;
        margin: 0;
        color: var(--primaryTextColor);
      }

      .indicator{
        width: 4px;
        height: 18px;
        border-radius: 4px;
        background: var(--aurora-gradient);
        margin: 0;
      }
    }

    &__count{
      font-size: 12px;
      font-weight: 700;
      color: var(--secondaryTextColor);
      padding: 3px 10px;
      border-radius: 20px;
      background: color-mix(in srgb, var(--primaryTextColor) 7%, transparent);
    }

    .post_content{
      background: transparent;
      padding: 0;
      margin: 0;
      border-radius: 0;
    }

    .video{
      margin: 0;
      border-radius: 16px;
      overflow: hidden;
    }
  }

  /* ---------- track list ---------- */
  .aurora_tracks{
    margin: 0;

    .album_item{
      position: relative;
      overflow: hidden;
      background: color-mix(in srgb, var(--primaryTextColor) 4%, transparent);
      border: 1px solid transparent;
      border-radius: 14px;
      padding: 10px 14px;
      margin-bottom: 8px;
      transition: .22s ease;
      gap: 10px;

      &::before{
        content: "";
        position: absolute;
        inset-block: 0;
        inset-inline-start: 0;
        width: 3px;
        background: var(--aurora-gradient);
        opacity: 0;
        transition: opacity .22s ease;
      }

      &:last-child{ margin-bottom: 0; }

      &:hover{
        border-color: color-mix(in srgb, var(--primaryColor) 30%, transparent);
        background: color-mix(in srgb, var(--primaryColor) 7%, transparent);

        &::before{ opacity: 1; }
      }

      .increment{
        background: transparent;
        border: 1px solid var(--aurora-line);
        border-radius: 10px;
        color: var(--secondaryTextColor);
        font-size: 13px;
        font-weight: 700;
        height: 32px;
        width: 32px;
        margin: 0;
        margin-inline-end: 10px;
      }

      .play button,
      .play .ms-playlist-locked{
        width: 36px;
        height: 36px;
        margin: 0;
        margin-inline-end: 10px;
        border-radius: 50%;
        display: flex;
        align-items: center;
        justify-content: center;
        font-size: 19px;
        line-height: 0;
        border: none;
        color: var(--primaryTextBtn);
        background: var(--aurora-gradient);
        box-shadow: 0 10px 20px -12px color-mix(in srgb, var(--primaryColor) 90%, var(--ms-black));
        transition: transform .2s ease;

        &:hover{ transform: scale(1.06); }
      }

      .play .ms-playlist-locked{
        font-size: 14px;
        background: color-mix(in srgb, var(--primaryTextColor) 12%, transparent);
        color: var(--secondaryTextColor);
        box-shadow: none;
      }

      .album_item__title{
        font-size: 14px;
        font-weight: 700;
      }

      .album_item__artist a{
        background: transparent;
        border-color: var(--aurora-line);
        color: var(--secondaryTextColor);
      }

      .album_item__download,
      .album_item__lyrics,
      .album_item__playlist .ms-add-to-playlist{
        min-height: 34px;
        border-radius: 10px;
        box-shadow: none;
        background: color-mix(in srgb, var(--primaryTextColor) 8%, transparent);
        border: 1px solid var(--aurora-line);
        color: var(--primaryTextColor);

        i{ color: inherit; filter: none; }

        &:hover{
          transform: none;
          box-shadow: none;
          color: var(--primaryTextBtn);
          background: var(--secondaryColor);
          border-color: var(--secondaryColor);
        }
      }

      .album_item__playlist .ms-add-to-playlist{
        width: 34px;
        height: 34px;

        i{ color: inherit; }

        &:hover{
          transform: none;
          box-shadow: none;
          background: var(--primaryColor);
          border-color: var(--primaryColor);

          i{ color: var(--primaryTextBtn); }
        }
      }
    }
  }

  /* ---------- lyrics panel ---------- */
  .aurora_lyrics{
    &__expand{
      width: 32px;
      height: 32px;
      border-radius: 10px;
      outline: none;
      line-height: 0;
      color: var(--secondaryTextColor);
      background: transparent;
      border: 1px solid var(--aurora-line);
      transition: .2s ease;

      &:hover{
        color: var(--primaryColor);
        border-color: color-mix(in srgb, var(--primaryColor) 55%, transparent);
      }
    }

    &__body{
      max-height: 260px;
      overflow: hidden;
      position: relative;
      color: var(--primaryTextColor);
      line-height: 2.1;
      font-size: 13px;
      -webkit-mask-image: linear-gradient(to bottom, #000 65%, transparent 100%);
      mask-image: linear-gradient(to bottom, #000 65%, transparent 100%);
    }
  }

  /* ---------- sidebar ---------- */
  .aurora_sticky{
    position: sticky;
    top: 100px;
  }

  .aurora_download_grid{
    display: grid;
    grid-template-columns: 1fr;
    gap: 8px;
    margin: 0;

    &--wide{
      grid-template-columns: repeat(auto-fill, minmax(230px, 1fr));
    }

    a{
      display: flex;
      align-items: center;
      gap: 12px;
      margin: 0;
      padding: 10px 12px;
      border-radius: 14px;
      background: color-mix(in srgb, var(--primaryTextColor) 5%, transparent);
      border: 1px solid var(--aurora-line-soft);
      color: var(--primaryTextColor);
      transition: .2s ease;

      &:hover{
        color: var(--primaryTextColor);
        border-color: color-mix(in srgb, var(--primaryColor) 40%, transparent);
        background: color-mix(in srgb, var(--primaryColor) 8%, transparent);
        transform: translateY(-2px);

        .aurora_dl__icon{
          background: var(--aurora-gradient);
          color: var(--primaryTextBtn);
        }
      }
    }
  }

  .aurora_dl{
    &__icon{
      flex: 0 0 auto;
      width: 36px;
      height: 36px;
      border-radius: 12px;
      display: flex;
      align-items: center;
      justify-content: center;
      font-size: 16px;
      line-height: 0;
      color: var(--primaryColor);
      background: color-mix(in srgb, var(--primaryColor) 12%, transparent);
      transition: .2s ease;

      i{ margin: 0; }
    }

    &__text{
      display: flex;
      flex-direction: column;
      gap: 2px;
      min-width: 0;

      strong{
        font-size: 13px;
        font-weight: 700;
      }

      small{
        font-size: 10px;
        font-weight: 600;
        letter-spacing: .5px;
        color: var(--secondaryTextColor);
      }
    }
  }

  .aurora_download_title{
    margin: 16px 0 10px;

    p{
      margin: 0;
      font-size: 12px;
      font-weight: 700;
      color: var(--secondaryTextColor);
    }
  }

  .aurora_meta{
    &__list{
      display: flex;
      flex-direction: column;
    }

    &__item{
      display: flex;
      align-items: flex-start;
      justify-content: space-between;
      gap: 12px;
      padding: 11px 0;
      border-bottom: 1px dashed var(--aurora-line-soft);
      font-size: 12px;

      &:last-child{ border-bottom: none; }

      > span:first-child{
        display: inline-flex;
        align-items: center;
        gap: 7px;
        color: var(--secondaryTextColor);
        white-space: nowrap;

        i{ font-size: 14px; color: var(--primaryColor); }
      }
    }

    &__value{
      text-align: end;
      color: var(--primaryTextColor);

      a{
        color: var(--primaryTextColor);

        &:hover{ color: var(--primaryColor); }
      }
    }
  }

  /* ---------- misc blocks ---------- */
  .aurora_tags{
    background: var(--aurora-panel-bg);
    border: 1px solid var(--aurora-line-soft);
    border-radius: var(--aurora-radius);
    box-shadow: var(--aurora-shadow);
  }

  .aurora_related,
  .aurora_comments{
    margin-top: 6px;

    .latestSongs__header h3,
    .content__header h3{
      display: flex;
      align-items: center;
      gap: 10px;
      font-size: 15px;
      font-weight: 700;
      color: var(--primaryTextColor);
    }

    .indicator{
      width: 4px;
      height: 18px;
      border-radius: 4px;
      background: var(--aurora-gradient);
      margin: 0;
    }
  }

  .aurora_comments{
    // background: var(--aurora-panel-bg);
    // border: 1px solid var(--aurora-line-soft);
    border-radius: var(--aurora-radius);
    // box-shadow: var(--aurora-shadow);
    padding: 20px;
    margin-bottom: 26px;

    .content__header{
      margin: 0 0 16px;
    }
  }

  .musicsara_vip_login{
    border-radius: var(--aurora-radius);
    margin-bottom: 20px;
  }
}

html.light{
  .aurora_demo{
    --aurora-line: color-mix(in srgb, var(--primaryTextColor) 14%, transparent);
    --aurora-line-soft: color-mix(in srgb, var(--primaryTextColor) 9%, transparent);
    --aurora-shadow: 0 18px 38px -26px var(--ms-shadow-color);

    .aurora_hero__backdrop{ opacity: .35; }
    .aurora_hero__glow{ opacity: .35; }
    .aurora_hero__cover img{ box-shadow: 0 22px 44px -24px rgba(0, 0, 0, .45); }
  }
}

@media (max-width: 991px){
  .aurora_demo{
    .aurora_sticky{ position: static; }
  }
}

@media (max-width: 767px){
  .aurora_demo{
    .aurora_hero{
      padding: 20px;
      border-radius: 20px;
    }

    .aurora_hero__inner{
      flex-direction: column;
      align-items: center;
      text-align: center;
      gap: 18px;
    }

    .aurora_hero__cover{
      flex: 0 0 auto;
      width: 190px;
    }

    .aurora_hero__genres,
    .aurora_hero__artists,
    .aurora_hero__stats,
    .aurora_hero__actions{
      justify-content: center;
    }

    .aurora_hero__actions .share_dialog{
      inset-inline-end: auto;
      inset-inline-start: 50%;
      transform: translateX(-50%);
    }

    .aurora_tracks .album_item{
      align-items: flex-start;

      .leftSide{
        flex-wrap: wrap;
        width: 100%;
        margin-top: 10px;
      }
    }
  }
}
